  /**
   * 透析情報（クール＆治療方法）取得
   *
   * @param bodyData         透析情報（クール＆治療方法）取得用の指示共通抽出条件
   * @param validationResult 受信データのバリデーション結果
   */
  @PostMapping("/KurAndTreatmentList")
  public ResponseEntity<List<OrdMainKurAndTreatmentList>> getOrdMainKurAndTreatmentList(
    @Validated @RequestBody ApiEntityOrdMain.ValiIndCommSearchConditions bodyData, BindingResult validationResult
  ) throws URISyntaxException {
    // 受信データログ出力
    //add FNSI-「コンソール出力のみで、ログに出力されていないメッセージがある」を改修 江 start
    EventLogMessage eventLogMessage = new EventLogMessage();
    eventLogMessage.setLogMessage("facility_cd:" + bodyData.getFacility_cd()
      + " pat_id:" + bodyData.getPat_id()
      + " ind_start_date:" + bodyData.getInd_start_date()
      + " ind_end_date:" + bodyData.getInd_end_date()
      + " week_pattern:" + bodyData.getWeek_pattern());
    logService.log(LogLevel.INFO, eventLogMessage, "", SERVICE_NAME.FNSI, null);
    //add FNSI-「コンソール出力のみで、ログに出力されていないメッセージがある」を改修 江 end

    // バリデーションエラーチェック
    if (validationResult.hasErrors()) {
      // バリデーションエラーが発生した場合はパラメータ異常扱い
      //add FNSI-「コンソール出力のみで、ログに出力されていないメッセージがある」を改修 江 start
      eventLogMessage = new EventLogMessage();
      eventLogMessage.setLogMessage("result:" + validationResult.toString());
      logService.log(LogLevel.INFO, eventLogMessage, "", SERVICE_NAME.FNSI, null);
      //add FNSI-「コンソール出力のみで、ログに出力されていないメッセージがある」を改修 江 end
      for (ObjectError error : validationResult.getFieldErrors()) {
        //add FNSI-「コンソール出力のみで、ログに出力されていないメッセージがある」を改修 江 start
        eventLogMessage = new EventLogMessage();
        eventLogMessage.setLogMessage("error:" + error.getDefaultMessage());
        logService.log(LogLevel.ERROR, eventLogMessage, "", SERVICE_NAME.FNSI, null);
        //add FNSI-「コンソール出力のみで、ログに出力されていないメッセージがある」を改修 江 end
      }
      return new ResponseEntity<>(null, HttpStatus.BAD_REQUEST);
    }

    // 曜日パターン情報加工
    List<Integer> weekPattern = new ArrayList<Integer>();
    weekPattern.add(0);
    if ((null != bodyData.getWeek_pattern()) && (false == "".equals(bodyData.getWeek_pattern()))) {
      weekPattern = IndicationUtils.getWeekPattern(bodyData.getWeek_pattern());
      if (null == weekPattern) {
        // 曜日パターン情報加工に発生した場合はパラメータ異常扱い
        return new ResponseEntity<>(null, HttpStatus.BAD_REQUEST);
      }
    }

    // データ取得
    String dateFrom = ((null != bodyData.getInd_start_date()) && (false == "".equals(bodyData.getInd_start_date()))) ? bodyData.getInd_start_date().replaceAll("-", "") : null;
    String dateTo = ((null != bodyData.getInd_end_date()) && (false == "".equals(bodyData.getInd_end_date()))) ? bodyData.getInd_end_date().replaceAll("-", "") : null;
    List<OrdMainKurAndTreatmentList> listRet = ordMainService.getOrdMainKurAndTreatmentList(
      bodyData.getFacility_cd(),
      Long.parseLong(bodyData.getPat_id()),
      dateFrom,
      dateTo,
      weekPattern,
      "0");
    // 戻り値チェック
    if (null == listRet) {
      // 取得に失敗した場合は内部エラー扱い
      return new ResponseEntity<>(null, HttpStatus.INTERNAL_SERVER_ERROR);
    }

    return new ResponseEntity<>(listRet, HttpStatus.OK);
  }

