//      ordMain.setIndTreatStartTime(kurStartTime);
//      ordMain.setIndKurName(mstKur.getKurName());
//    }
    // add 10196 by kangjie 20240119 end
    // ベッドコードを格納する
    ordMain.setIndBedCd(Integer.parseInt(bodyData.getInd_bed_cd()));
    // add 10196 by kangjie 20240119 start
    ordMain.setIndBedName(null);
//    if (ordMain.getIndBedCd().equals(0)) {
//      // ベッド名をnullで更新
