//      // ベッド名を設定する
//      ordMain.setIndBedName(mstInfoService.findBedNameByBedCd(Long.parseLong(bodyData.getInd_bed_cd())));
//    }
    // add 10196 by kangjie 20240119 end
    // 投与薬剤有無 = 無：含めない場合
    if (!isIncludingMedicine) {
      // 空配列の格納
      ordMain.setIndMediInfo("[]");
    }
    // 指示者ID・更新者IDを適用する
    ordMain = ordMainService.addIndUserAndUpdUserInfo(ordMain, Long.parseLong(bodyData.getInd_user()), Long.parseLong(bodyData.getUpd_user()));
    List<String> condKey = Arrays.asList("value_name_1", "unit", "ind_user_last_name", "ind_user_first_name", "upd_user_last_name", "upd_user_first_name");
    // 条件送信後展開情報を初期化する
    ordMain = this.InitializeOrdCondSendInfo(ordMain);
    //mod #11841 【たくしん会】ord_mainの登録不正 zrx start
    // add 10196 by kangjie 20240122 start
//    ordMain = this.delJSONKey(ordMain);
    ordMain = ordMainService.delJSONKey(ordMain);
    // add 10196 by kangjie 20240122 end
    //mod #11841 【たくしん会】ord_mainの登録不正 zrx end

    // add FNSI-予定コピー仕様修正、障害票一覧_患者経過総合ビューアNo.16-19 李 start
