  private void setAnticoagulantUnit(List<OrdMain> sendAfterOrdMain, JSONObject indCondInfo) {
    if (indCondInfo.has("25")) {
      OrdMain ordMain = sendAfterOrdMain.get(0);
      String unit = null;
      Integer unitDecimalPoint = null;
      if (!isNullValue(indCondInfo.optJSONObject("25").optString("value", ""))) {
        int medicineType = indCondInfo.optJSONObject("25").getInt("medicine_type");
        int medicineCd = indCondInfo.optJSONObject("25").getInt("value");
        if (1 == medicineType) {
          MstMedicine mstMedicine = mstMedicineDao.selectAllByMediCd(medicineCd);
          unit = mstMedicine.getUnit();
          unitDecimalPoint = mstMedicine.getUnitDecimalPoint();
        }else {
          MstMedicineMix mstMedicineMix = mstMedicineMixDao.selectByCd(ordMain.getFacilityCd(), medicineCd);
          unit = mstMedicineMix.getUnit();
          unitDecimalPoint = mstMedicineMix.getUnitDecimalPoint();
        }
      }

      String indCondInfo1 = ordMain.getIndCondInfo();
      JSONObject indCondJson = new JSONObject(indCondInfo1);
      if (!indCondInfo.has("26")) {
        String dbValue = indCondJson.optJSONObject("26").getString("value");
        JSONObject jsonObject = new JSONObject();
        jsonObject.put("value",unitDecimalPoint == null ? dbValue : new BigDecimal(dbValue).setScale(unitDecimalPoint,RoundingMode.DOWN).toPlainString());
        jsonObject.put("unit",unit == null ? JSONObject.NULL : unit);
        indCondInfo.put("26",jsonObject);
      }
      if (!indCondInfo.has("27")) {
        String dbValue = indCondJson.optJSONObject("27").getString("value");
        JSONObject jsonObject = new JSONObject();
        jsonObject.put("value",unitDecimalPoint == null ? dbValue : new BigDecimal(dbValue).setScale(unitDecimalPoint,RoundingMode.DOWN).toPlainString());
        jsonObject.put("unit",unit == null ? JSONObject.NULL : unit+"/h");
        indCondInfo.put("27",jsonObject);
      }
      if (!indCondInfo.has("28")) {
        String dbValue = indCondJson.optJSONObject("28").getString("value");
        JSONObject jsonObject = new JSONObject();
        jsonObject.put("value",unitDecimalPoint == null ? dbValue : new BigDecimal(dbValue).setScale(unitDecimalPoint,RoundingMode.DOWN).toPlainString());
        jsonObject.put("unit",unit == null ? JSONObject.NULL : unit);
        indCondInfo.put("28",jsonObject);
      }
    }

  }
  // add #10247 施設設定マスタの設定にかかわらず、総量計算がされず、動作が正しくない 20240303 ztc start
  public static String decimalPlaces(String numStr) {
    if (!numStr.contains(".")) {
      return "0";
    }
    int decimalIndex = numStr.indexOf('.');
    String decimalPart = numStr.substring(decimalIndex + 1);
    return "0." + String.format("%-" + decimalPart.length() + "s", "").replace(' ', '0');
  }
