  /**
   * 抗凝固剤維持総量情報の追加
   *
   * @summary 抗凝固剤維持総量非表示の場合、値はする
   */
  // mod 11790 抗凝固剤持続総量の計算をするとマイナスになる事がある zkm start
  private Map<Long,JSONObject>  getCoagulantInfo(JSONObject condInfo, Map<Long,String> ordMainMap, String accountItemCd, String antiCoagulantFlowRate) {
    // 抗凝固剤の総量は1日につきます
    Map<Long, JSONObject> totalQualityGroupByOrdNo = new HashMap<>();
    ordMainMap.forEach((key, value) -> {
      JSONObject ordCondInfo = new JSONObject(value);
      // 抗凝固剤持続総量
      Double coagulant = 0.0;
      String treatTime = "";
      if (condInfo.has(String.valueOf(1))) {
        treatTime = String.valueOf(condInfo.getJSONObject(String.valueOf(1)).get("value"));
      } else {
        if (ordCondInfo.has(String.valueOf(1))) {
          treatTime = String.valueOf(ordCondInfo.getJSONObject(String.valueOf(1)).get("value"));
        }
      }
      if (StringUtils.hasText(treatTime)) {

        // 抗凝固剤時速速度
        String ordAntiCoagulantFlowRate = "";
        if (condInfo.has(String.valueOf(27))) {
          ordAntiCoagulantFlowRate = String.valueOf(condInfo.getJSONObject(String.valueOf(27)).get("value"));
        } else {
          if (ordCondInfo.has(String.valueOf(27))) {
            ordAntiCoagulantFlowRate = String.valueOf(ordCondInfo.getJSONObject(String.valueOf(27)).get("value"));
          }
        }
        // IP電源自動切
        String isIpAutoOff = "";
        if (condInfo.has(String.valueOf(35))) {
          isIpAutoOff = String.valueOf(condInfo.getJSONObject(String.valueOf(35)).get("value"));
        } else {
          if (ordCondInfo.has(String.valueOf(35))) {
            isIpAutoOff = String.valueOf(ordCondInfo.getJSONObject(String.valueOf(35)).get("value"));
          }
        }
        // IP電源自動切時間
        String ipAutoOffTiming = "";
        if (condInfo.has(String.valueOf(36))) {
          ipAutoOffTiming = String.valueOf(condInfo.getJSONObject(String.valueOf(36)).get("value"));
        } else {
          if (ordCondInfo.has(String.valueOf(36))) {
            ipAutoOffTiming = String.valueOf(ordCondInfo.getJSONObject(String.valueOf(36)).get("value"));
          }
        }
        // 抗凝固剤維持総量下记以外の场合は非表示となります。
        // "1":抗凝固剤持続総量表示 "4":抗凝固剤持続総量とIPワンショット量表示
        // "5":抗凝固剤持続総量とIP速度表示、"7":抗凝固剤持続総量とIPワンショット量とIP速度表示
        if ((!"1".equals(accountItemCd) && !"4".equals(accountItemCd) && !"5".equals(accountItemCd) && !"7".equals(accountItemCd))) {

          // ケース：抗凝固剤持続速度空欄：抗凝固剤持続総量も空欄＝未登録で展開
          if (StringUtils.isEmpty(ordAntiCoagulantFlowRate) || "null".equals(ordAntiCoagulantFlowRate)) {
            coagulant = null;
            // ケース：治療時間未登録または0：抗凝固剤持続総量を0で更新
          } else if ("0".equals(treatTime)) {
            coagulant = 0.0;
          } else
            // IP電源自動切変更の場合
            if ((!StringUtils.isEmpty(antiCoagulantFlowRate) && !"null".equals(antiCoagulantFlowRate))
              || !StringUtils.isEmpty(isIpAutoOff) || !StringUtils.isEmpty(ipAutoOffTiming)) {
              // 切の場合
              if ("0".equals(isIpAutoOff)) {
                // 抗凝固剤時速速度変更の場合
                if (!StringUtils.isEmpty(antiCoagulantFlowRate) && !"null".equals(antiCoagulantFlowRate)) {

                  coagulant = (Double.parseDouble(antiCoagulantFlowRate) * Double.parseDouble(treatTime)) / 60;
                } else if (!StringUtils.isEmpty(ordAntiCoagulantFlowRate) && !"null".equals(ordAntiCoagulantFlowRate)) {

                  coagulant = (Double.parseDouble(ordAntiCoagulantFlowRate) * Double.parseDouble(treatTime)) / 60;
                }
              } else {
                // 抗凝固剤時速速度とIP電源自動切時間変更の場合
                if ((!StringUtils.isEmpty(antiCoagulantFlowRate) && !"null".equals(antiCoagulantFlowRate)) &&
                  (!StringUtils.isEmpty(ipAutoOffTiming) && !"null".equals(ipAutoOffTiming))) {

                  coagulant = Double.parseDouble(antiCoagulantFlowRate) * ((Double.parseDouble(treatTime) - Double.parseDouble(ipAutoOffTiming)) / 60);
                  // 抗凝固剤時速速度変更の場合
                } else if ((!StringUtils.isEmpty(antiCoagulantFlowRate) && !"null".equals(antiCoagulantFlowRate)) && StringUtils.isEmpty(ipAutoOffTiming) &&
                  (!StringUtils.isEmpty(ipAutoOffTiming) && !"null".equals(ipAutoOffTiming))) {

                  coagulant = Double.parseDouble(antiCoagulantFlowRate) * ((Double.parseDouble(treatTime) - Double.parseDouble(ipAutoOffTiming)) / 60);
                  // IP電源自動切時間変更の場合
                } else if (StringUtils.isEmpty(antiCoagulantFlowRate) && (!StringUtils.isEmpty(ipAutoOffTiming) && !"null".equals(ipAutoOffTiming)) &&
                  (!StringUtils.isEmpty(ordAntiCoagulantFlowRate) && !"null".equals(ordAntiCoagulantFlowRate))) {

                  coagulant = Double.parseDouble(ordAntiCoagulantFlowRate) * ((Double.parseDouble(treatTime) - Double.parseDouble(ipAutoOffTiming)) / 60);
                  // 抗凝固剤時速速度とIP電源自動切時間変更なしの場合
                } else if (StringUtils.isEmpty(antiCoagulantFlowRate) && StringUtils.isEmpty(ipAutoOffTiming) &&
                  (!StringUtils.isEmpty(ordAntiCoagulantFlowRate) && !"null".equals(ordAntiCoagulantFlowRate)) &&
                  (!StringUtils.isEmpty(ipAutoOffTiming) && !"null".equals(ipAutoOffTiming))) {

                  coagulant = Double.parseDouble(ordAntiCoagulantFlowRate) * ((Double.parseDouble(treatTime) - Double.parseDouble(ipAutoOffTiming)) / 60);
                }
              }
              // IP電源自動切変更なしの場合
            } else {
              // 切の場合
              if ("0".equals(isIpAutoOff)) {
                // 抗凝固剤時速速度変更の場合
                if (!StringUtils.isEmpty(antiCoagulantFlowRate) && !"null".equals(antiCoagulantFlowRate)) {

                  coagulant = (Double.parseDouble(antiCoagulantFlowRate) * Double.parseDouble(treatTime)) / 60;
                } else if (!StringUtils.isEmpty(ordAntiCoagulantFlowRate) && !"null".equals(ordAntiCoagulantFlowRate)) {

                  coagulant = (Double.parseDouble(ordAntiCoagulantFlowRate) * Double.parseDouble(treatTime)) / 60;
                }
              } else {
                // 抗凝固剤時速速度とIP電源自動切時間変更の場合
                if ((!StringUtils.isEmpty(antiCoagulantFlowRate) && !"null".equals(antiCoagulantFlowRate)) &&
                  (!StringUtils.isEmpty(ipAutoOffTiming) && !"null".equals(ipAutoOffTiming))) {

                  coagulant = Double.parseDouble(antiCoagulantFlowRate) * ((Double.parseDouble(treatTime) - Double.parseDouble(ipAutoOffTiming)) / 60);
                  // 抗凝固剤時速速度変更の場合
                } else if ((!StringUtils.isEmpty(antiCoagulantFlowRate) && !"null".equals(antiCoagulantFlowRate)) && StringUtils.isEmpty(ipAutoOffTiming) &&
                  (!StringUtils.isEmpty(ipAutoOffTiming) && !"null".equals(ipAutoOffTiming))) {

                  coagulant = Double.parseDouble(antiCoagulantFlowRate) * ((Double.parseDouble(treatTime) - Double.parseDouble(ipAutoOffTiming)) / 60);
                  // IP電源自動切時間変更の場合
                } else if (StringUtils.isEmpty(antiCoagulantFlowRate) && (!StringUtils.isEmpty(ipAutoOffTiming) && !"null".equals(ipAutoOffTiming)) &&
                  (!StringUtils.isEmpty(ordAntiCoagulantFlowRate) && !"null".equals(ordAntiCoagulantFlowRate))) {

                  coagulant = Double.parseDouble(ordAntiCoagulantFlowRate) * ((Double.parseDouble(treatTime) - Double.parseDouble(ipAutoOffTiming)) / 60);
                  // 抗凝固剤時速速度とIP電源自動切時間変更なしの場合
                } else if (StringUtils.isEmpty(antiCoagulantFlowRate) && StringUtils.isEmpty(ipAutoOffTiming) &&
                  (!StringUtils.isEmpty(ordAntiCoagulantFlowRate) && !"null".equals(ordAntiCoagulantFlowRate)) &&
                  (!StringUtils.isEmpty(ipAutoOffTiming) && !"null".equals(ipAutoOffTiming))) {

                  coagulant = Double.parseDouble(ordAntiCoagulantFlowRate) * ((Double.parseDouble(treatTime) - Double.parseDouble(ipAutoOffTiming)) / 60);
                }
              }
            }
          if (ordCondInfo.has(String.valueOf(28))) {
            JSONObject obj = new JSONObject(String.valueOf(ordCondInfo.getJSONObject(String.valueOf(28))));
            String decPoint = "0";
            if (obj.has("value") && Objects.nonNull(obj.get("value"))) {
              value = obj.get("value").toString();
              if (value.contains(".")) {
                decPoint = String.valueOf(value.length() - value.indexOf('.') - 1);
              }
              if (decPoint.compareTo("0") <= 0) {
                decPoint = "0";
              }
            } else {
              decPoint = "0";
            }
            if (obj.has("value_name_1")) {
              obj.put("value_name_1",
                Objects.isNull(coagulant) ? JSONObject.NULL : String.format("%." + decPoint + "f", coagulant < 0.0 ? 0.0 : coagulant));
            }
            obj.put("value", Objects.isNull(coagulant) ? JSONObject.NULL : String.format("%." + decPoint + "f", coagulant < 0.0 ? 0.0 : coagulant));
            totalQualityGroupByOrdNo.put(key, obj);
            condInfo.put("28", obj);
          }
        }
      }
    });
    return totalQualityGroupByOrdNo;
  }
