  //  @Async("doSomethingExecutor")
  public void asyncUpdSchedule(Map<String, String> params, String pcKey) {

    ThreadPoolTaskExecutor executor = (ThreadPoolTaskExecutor) AppContextUtils.getBean("doSomethingExecutor");

    String facilityCd = params.get("facilityCd");
    Long userId = Long.valueOf(params.get("userId"));
    Long updUserId = Long.valueOf(params.get("updUserId"));
    EventLogMessage eventLogMessage = new EventLogMessage();
    eventLogMessage.setLogMessage("facility_cd: " + facilityCd);
    logService.log(LogLevel.INFO, eventLogMessage, "", SERVICE_NAME.FNSI, null);

    if (executor != null) {
      executor.execute(() -> {
        try {
          ordMainService.initializeProcessCount(facilityCd, pcKey);
          //mod #10634 クールマスタで標準治療開始時刻を変更した際のダミー予定・連携イベント作成処理不正 zrx start
//          OrdMainForJournal result = ordMainService.updateIndScheduleOnceForAll(facilityCd, userId, updUserId, pcKey);
          List<MstKur> oldMstKurList = new ArrayList<>();
          String oldMstKurJson = params.get("oldMstKur");
          if (oldMstKurJson != null && !oldMstKurJson.isEmpty()) {
            ObjectMapper objectMapper = new ObjectMapper();
            oldMstKurList = objectMapper.readValue(oldMstKurJson, new TypeReference<List<MstKur>>() {});
          }
          OrdMainForJournal result = ordMainService.updateIndScheduleOnceForAll(facilityCd, userId, updUserId, pcKey, oldMstKurList);
          //mod #10634 クールマスタで標準治療開始時刻を変更した際のダミー予定・連携イベント作成処理不正 zrx end
          List<OrdMain> journalList = result.getJournalList();
          patTreatmentPatternService.updatePatTreatmentPatternOnceForAll(facilityCd, userId, updUserId);

          /* #10282 Create a new interface to synchronize processing progress. START */
          ordMainService.setUpdKurProcess(pcKey, 15);
          /* #10282 Create a new interface to synchronize processing progress. END */

          journalService.sendJournal(journalList, facilityCd, userId);

          /* #10282 Create a new interface to synchronize processing progress. START */
          ordMainService.setUpdKurProcess(pcKey, 16);
          /* #10282 Create a new interface to synchronize processing progress. END */
        } catch (Exception e) {
          // マスタが取得できなかった場合
          // #9700 イベントログに出るべきではないもの、判読不可能なログがある 20260407 mod yangxuewang start
          eventLogMessage.setLogMessage(ExcetionStackTraceToString(e));
          // #9700 イベントログに出るべきではないもの、判読不可能なログがある 20260407 mod yangxuewang end
          eventLogMessage.setFacilityCd(facilityCd);
          logService.log(LogLevel.ERROR, eventLogMessage, "", SERVICE_NAME.FNSI, null);

          /* #10282 Create a new interface to synchronize processing progress. START */
          ordMainService.mainProcessHasFail(pcKey);
          /* #10282 Create a new interface to synchronize processing progress. END */
        }
      });
    }
  }

  /**
   * Retrieve the current processing progress from the global cache variables.
   *
   * @param facilityCd 施設コード.
   * @return  current processing progress
   */
  @GetMapping("/getUpdKurProcess/{facilityCd}")
  public ResponseEntity<OrdMainForJournal> getUpdKurProcess(@PathVariable String facilityCd) {
    NtssUser user = (NtssUser) SecurityContextHolder.getContext().getAuthentication().getPrincipal();
    String pcKey = (user != null) ? user.getFacilityCd() + user.getSessionId() : facilityCd;

    OrdMainForJournal responseObj = ordMainService.getUpdKurProcess(pcKey);
    if (Objects.isNull(responseObj)) new ResponseEntity<>(null, HttpStatus.INTERNAL_SERVER_ERROR);

    return new ResponseEntity<>(responseObj, HttpStatus.OK);
  }
