  @PostMapping("/sharingInfo/getOrdMainOfIndMediInfo")
  public ResponseEntity<List<OrdMain>> getOrdMainOfIndMediInfo(
    @Validated @RequestBody ApiEntityOrdMain.ValiIndMediInfoSearchCondition bodyData,
    BindingResult validationResult ){
    if (StringUtils.isEmpty(bodyData.getStartTime())){
      EventLogMessage eventLogMessage = new EventLogMessage();
      eventLogMessage.setSqlIdentification("getOrdMainOfIndMediInfo Exception: startTime is null");
      logService.log(LogLevel.ERROR, eventLogMessage, null, SERVICE_NAME.FNSI, null);
      return new ResponseEntity<>(new ArrayList<>(),HttpStatus.OK);
    }
    if (StringUtils.isEmpty(bodyData.getFacilityCd())){
      EventLogMessage eventLogMessage = new EventLogMessage();
      eventLogMessage.setSqlIdentification("getOrdMainOfIndMediInfo Exception: facilityCd is null");
      logService.log(LogLevel.ERROR, eventLogMessage, null, SERVICE_NAME.FNSI, null);
      return new ResponseEntity<>(new ArrayList<>(),HttpStatus.OK);
    }
    if (StringUtils.isEmpty(bodyData.getPatId())){
      EventLogMessage eventLogMessage = new EventLogMessage();
      eventLogMessage.setSqlIdentification("getOrdMainOfIndMediInfo Exception: patId is null");
      logService.log(LogLevel.ERROR, eventLogMessage, null, SERVICE_NAME.FNSI, null);
      return new ResponseEntity<>(new ArrayList<>(),HttpStatus.OK);
    }
    List<OrdMain> list = ordMainService.getOrdMainOfIndMediInfo(bodyData);
    return new ResponseEntity<>(list,HttpStatus.OK);
  }
