  /**
   * 治療予定の中止処理
   * ①バリデーションチェック
   * ②治療予定の中止
   *
   * @param bodyData         治療予定の抽出条件および治療情報
   * @param validationResult 受信データのバリデーション結果
   * @return
   * @throws URISyntaxException
   * @throws ParseException
   * @throws JSONException
   */
  @PostMapping("deleteIndPlan")
  public ResponseEntity<String> deleteIndPlan(
    @Validated @RequestBody ApiEntityOrdMain.ValiDeleteTreatPlan bodyData, BindingResult validationResult
  ) throws URISyntaxException, ParseException, JSONException {

    //add FNSI-「コンソール出力のみで、ログに出力されていないメッセージがある」を改修 江 start
    EventLogMessage eventLogMessage = new EventLogMessage();
    eventLogMessage.setLogMessage("deleteIndPlanを開始");
    logService.log(LogLevel.INFO, eventLogMessage, "", SERVICE_NAME.FNSI, null);
    eventLogMessage = new EventLogMessage();
    eventLogMessage.setLogMessage("pat_id: " + bodyData.getPat_id()
      + " start_date: " + bodyData.getStart_date()
      + " end_date: " + bodyData.getEnd_date()
      + " ind_user_id: " + bodyData.getInd_user_id()
      + " upd_user_id: " + bodyData.getUpd_user_id()
      + " treatment_cd: " + bodyData.getTreatment_cd()
      + " kur_cd: " + bodyData.getKur_cd()
    );
    logService.log(LogLevel.INFO, eventLogMessage, "", SERVICE_NAME.FNSI, null);
    //add FNSI-「コンソール出力のみで、ログに出力されていないメッセージがある」を改修 江 end

    // バリデーションエラーチェック
    if (validationResult.hasErrors()) {
      // バリデーションエラーが発生した場合はパラメータ異常扱い
      //add FNSI-「コンソール出力のみで、ログに出力されていないメッセージがある」を改修 江 start
      eventLogMessage = new EventLogMessage();
      eventLogMessage.setLogMessage("result:" + validationResult);
      logService.log(LogLevel.INFO, eventLogMessage, "", SERVICE_NAME.FNSI, null);
      //add FNSI-「コンソール出力のみで、ログに出力されていないメッセージがある」を改修 江 end
      for (ObjectError error : validationResult.getFieldErrors()) {
        //add FNSI-「コンソール出力のみで、ログに出力されていないメッセージがある」を改修 江 start
        eventLogMessage = new EventLogMessage();
        eventLogMessage.setLogMessage("error:" + error.getDefaultMessage());
        logService.log(LogLevel.ERROR, eventLogMessage, "", SERVICE_NAME.FNSI, null);
        //add FNSI-「コンソール出力のみで、ログに出力されていないメッセージがある」を改修 江 end
      }
      HttpStatus status = HttpStatus.BAD_REQUEST;
      //引数は、ボディデータ,ヘッダーデータ,ステータス
      ResponseEntity<String> re = new ResponseEntity<>("パラメータエラー", null, status);
      return re;
    }

    // add #10712 日次スケジュール自動延長処理の除外考慮修正 zkm start
    if (Boolean.FALSE.toString().equals(bodyData.getIs_deadline())) {
      PatMain patMain = patMainDao.selectById(Long.parseLong(bodyData.getPat_id()));

      // スケジュール延長処理中の場合、予定作成を中止する
      if (("1").equals(patMain.getSch_ext_status())) {
        JSONObject msgJson = new JSONObject("{}");
        msgJson.put("msgCd", 22020004);
        return new ResponseEntity<>(msgJson.toString(), HttpStatus.OK);
      }
    }
    // add #10712 日次スケジュール自動延長処理の除外考慮修正 zkm end

    // 患者ID
    Long patId = Long.parseLong(bodyData.getPat_id());

    // 開始日(治療日) yyyy-MM-dd形式⇒yyyyMMdd形式
    SimpleDateFormat startDateFormat = new SimpleDateFormat("yyyy-MM-dd");
    Date startDate = startDateFormat.parse(bodyData.getStart_date());
    String dialysisDateFrom = new SimpleDateFormat("yyyyMMdd").format(startDate);

    // 終了日(治療日) yyyy-MM-dd形式⇒yyyyMMdd形式
    SimpleDateFormat endDateFormat = new SimpleDateFormat("yyyy-MM-dd");
    Date endDate = endDateFormat.parse(bodyData.getEnd_date());
    String dialysisDateTo = new SimpleDateFormat("yyyyMMdd").format(endDate);

    // クール
    List<Integer> kurCdList = this.getValueList(bodyData.getKur_cd());

    //曜日
    List<Integer> weeksArray = new ArrayList<>();
    // 曜日パターンの指定がない場合
    if (null == bodyData.getWeek_pattern()) {
      for (int date = Integer.parseInt(dialysisDateFrom); date <= Integer.parseInt(dialysisDateTo); date++) {
        String dateStr = String.valueOf(date);
        SimpleDateFormat dateFormat = new SimpleDateFormat("yyyyMMdd");
        Date treatDay = dateFormat.parse(dateStr);
        Calendar cal = Calendar.getInstance();
        cal.setTime(treatDay);
        int dayOfWeek = cal.get(Calendar.DAY_OF_WEEK) - 1;
        if (0 == dayOfWeek) dayOfWeek = 7;
        weeksArray.add(dayOfWeek);
        if (7 == weeksArray.size()) break;
      }
    } else {
      weeksArray = IndicationUtils.getWeekPattern(bodyData.getWeek_pattern());
    }
    // 曜日リストの重複を削除
    weeksArray = weeksArray.stream().distinct().collect(Collectors.toList());

    // 中止対象治療情報リスト取得
    List<OrdMain> ordMainList = new ArrayList<>();
    try {
      ordMainList = ordMainService.findUpdateTarget(
        Long.parseLong(bodyData.getPat_id()),
        bodyData.getFacility_cd(),
        bodyData.getStart_date().replaceAll("-", ""),
        bodyData.getEnd_date().replaceAll("-", ""),
        weeksArray,
        this.getValueList(bodyData.getTreatment_cd()),
        this.getLongList(bodyData.getKur_cd())
      );
    } catch (Exception e) {
      // #9700 イベントログに出るべきではないもの、判読不可能なログがある 20260403 del yangxuewang start
//      e.printStackTrace();
      // #9700 イベントログに出るべきではないもの、判読不可能なログがある 20260403 del yangxuewang end
      //mod FNSI-「コンソール出力のみで、ログに出力されていないメッセージがある」を改修 江 start
      //EventLogMessage eventLogMessage = new EventLogMessage();
      eventLogMessage = new EventLogMessage();
      //mod FNSI-「コンソール出力のみで、ログに出力されていないメッセージがある」を改修 江 end
      // #9700 イベントログに出るべきではないもの、判読不可能なログがある 20260403 mod yangxuewang start
      eventLogMessage.setLogMessage(ExcetionStackTraceToString(e));
      if (bodyData != null && bodyData.getFacility_cd() != null) {
        eventLogMessage.setFacilityCd(bodyData.getFacility_cd());
      }
      // #9700 イベントログに出るべきではないもの、判読不可能なログがある 20260403 mod yangxuewang end
      logService.log(LogLevel.ERROR, eventLogMessage, "", SERVICE_NAME.FNSI, null);
    }

    //add #10266 start
    if(!StringUtils.hasText(bodyData.getOrd_no())){
      ordMainList = ordMainList.stream().filter(ord -> "0".equals(ord.getRstDialysisState())).collect(Collectors.toList());
    }
    if(ordMainList.size()<=0){
      return new ResponseEntity<>(new JSONObject("{}").toString(), null, HttpStatus.OK);
    }
    //add #10266 end

    // 更新対象リストから重複治療日リストを取り除く
    for (int i = ordMainList.size() - 1; - 1 < i; i--) {
      // 重複対象リストが格納されている場合
      if (null != bodyData.getDupulicate_treat_date()) {
        JSONArray dupulicateArray = new JSONArray(bodyData.getDupulicate_treat_date());
        for (int j = 0; j < dupulicateArray.length(); j++) {
          if (ordMainList.get(i).getTreatDate().equals(dupulicateArray.get(j).toString())) {
            // 更新対象から取り除く
            ordMainList.remove(i);
            break;
          }
        }
      }
    }

    // 戻り値情報
    JSONObject responseData = new JSONObject();

    // 条件送信キャンセル操作
    Map<String, List<OrdMain>> doCancelInfo = this.getDoCancelInfo(ordMainList);

    // 条件送信確認後以降を取り除いた更新対象を取得
    ordMainList = doCancelInfo.get("ordMainList");

    // 治療予定中止対象の日付リスト
    List<String> treatDateList = ordMainList.stream().map(item -> item.getTreatDate()).distinct().collect(Collectors.toList());
    responseData.put("treatDate", treatDateList);

    // add FNSI-チェックリスト仕様変更対応#401、#439_患者経過総合ビューア機能分。 周 start
    // 治療情報中止の場合「条件送信前⇒チェックリスト実績を物理削除」
    /* modify by chamaojia 2023-03-24 [6118] ループ処理を一括処理に変更 -- start */
    List<Long> ordNoList = ordMainList.stream().map(item -> item.getOrdNo()).distinct().collect(Collectors.toList());

    UpdateScheduleListDataResponse checkResponse;

    WeekPatternResponse dataInfo = new WeekPatternResponse();
    dataInfo.setIsEndDateUnset(Boolean.parseBoolean(bodyData.getIs_deadline()));
    dataInfo.setPatId(Long.parseLong(bodyData.getPat_id()));
    dataInfo.setDelWeekList(List.of(1,2,3,4,5,6,7));
    dataInfo.setFacilityCd(bodyData.getFacility_cd());
    dataInfo.setFromWeekList(new ArrayList<>());

    IndscheduleChangeUserSelectedInfo userSelectedInfo = new IndscheduleChangeUserSelectedInfo ();
    userSelectedInfo.setFacilitySetting3005SelectedVal(bodyData.getFacilitySettingEventValue());
    userSelectedInfo.setFacilitySetting1007SelectedVal(bodyData.getFacilitySettingExamValue());
    userSelectedInfo.setFacilitySetting1008SelectedVal(bodyData.getFacilitySettingRadValue());
    userSelectedInfo.setExamDeadlineSelectedVal(bodyData.getExamDeadlineSelectedVal());
    userSelectedInfo.setRadDeadlineSelectedVal(bodyData.getRadDeadlineSelectedVal());

    checkResponse =
      changeDayOfWeekPatternCheck.validateDayOfWeekPatternChange(
        new ArrayList<>(), ordNoList, dataInfo, userSelectedInfo
      );
    if (checkResponse.getMsgCdList() != null && !checkResponse.getMsgCdList().isEmpty()) {
      JSONObject msgJson = new JSONObject("{}");
      msgJson.put("msgCdList", checkResponse.getMsgCdList());

      return new ResponseEntity<>(msgJson.toString(), null, HttpStatus.OK);
    }

    Map<String, List<Object>> resultAllChangeBeforeDataInfoList = new HashMap<>();

    OrdMainDeleteServiceImpl.DeleteTreatPlanCommand data = new OrdMainDeleteServiceImpl.DeleteTreatPlanCommand();
    data.setPatId(Long.parseLong(bodyData.getPat_id()));
    data.setFacilityCd(bodyData.getFacility_cd());
    data.setIndKurCdList(this.getLongList(bodyData.getKur_cd()));

    data.setIndUserId(Long.parseLong(bodyData.getInd_user_id()));
    data.setUpdUserId(Long.parseLong(bodyData.getUpd_user_id()));

    data.setTreatCdList(this.getValueList(bodyData.getTreatment_cd()));

    data.setDeadline(Boolean.parseBoolean(bodyData.getIs_deadline()));

    OrdMainDeleteServiceImpl.DeleteTreatPlanResult  result = ordMainDeleteService.deleteTreatPlanAndProcessDependencies(data, ordMainList, weeksArray,
       resultAllChangeBeforeDataInfoList, userSelectedInfo, checkResponse, dataInfo, "indDelete");

    // 治療予定の中止に失敗した場合
    if (0 > result.getDeletedOrdMainCount()) {
      HttpStatus status = HttpStatus.INTERNAL_SERVER_ERROR;
      //引数は、ボディデータ,ヘッダーデータ,ステータス
      ResponseEntity<String> re = new ResponseEntity<>("レコードの更新に失敗しました。", null, status);
      return re;
    } else if (result.getDeletedOrdMainCount() > 0) {
      // 治療予定の中止が実行されている場合
      if (! "true".equals(bodyData.getIs_unregistered_ind_history())) {
        indHistoryAsyncService.createDeleteAsyncHistory(bodyData, ordMainList, weeksArray);
      }
    }
    List<OrdMain> doCancelList = doCancelInfo.get("doCancelList");
    String facilityCd = bodyData.getFacility_cd();

    // サービスの新しい次患者更新呼出統合処理を呼び出す
    nextPatService.CallNextPatChange(facilityCd, ordMainList);
    //mod #10412 次患者更新関連全体見直し対応 朴 end

    // 条件送信キャンセルを行なった場合、メッセージを表示
    if (doCancelList.size() > 0) {
      responseData.put("msgCd", 22010006);
    }

    // add #10553 ①10125のsys_coop_iniのEXAMIN_INFO IND_SEND_MODE設定に応じた動作切替が画面がで実現 #10125 piao start
    // 連携関連呼出
    try {
      String actionMode = "PAT_VIEWER_STOP";

      Long updUserId = Long.parseLong(bodyData.getUpd_user_id());
      List<Long> patIdList = new ArrayList<>();
      patIdList.add(patId);
      List<Object> objectList = new ArrayList<>(ordMainList);
      resultAllChangeBeforeDataInfoList.put("ord_main", objectList);

      List<JournalCreateRequestPayload> journalList = journalCreatePayloadService.createJournalPayload(facilityCd, null, resultAllChangeBeforeDataInfoList, patIdList, updUserId, actionMode);
      if (!org.apache.commons.collections.CollectionUtils.isEmpty(journalList)) {
        journalService.callCreateJournalForCtrNo(journalList);
      }
    } catch (Exception e) {
      //エラー
      eventLogMessage.setLogMessage("連携関連呼出 " + e.getMessage());
      logService.log(LogLevel.ERROR, eventLogMessage, LoggingConstant.FUNCTION_CODE.FUNC_SCHEDULE_LIST, SERVICE_NAME.FNSI, null);
    }
    // add #10553 ①10125のsys_coop_iniのEXAMIN_INFO IND_SEND_MODE設定に応じた動作切替が画面がで実現 #10125 piao end
    return new ResponseEntity<>(responseData.toString(), null, HttpStatus.OK);
  }
