  private void deleteEventAndBbs(@RequestBody @Validated ApiEntityOrdMain.ValiDeleteTreatPlan bodyData, Long patId, List<OrdMain> ordMainList) {
    ordMainList.forEach(i -> {
      List<PatEvent> patEvents = patEventService.selectByOrdNo(i.getOrdNo(), bodyData.getFacility_cd());
      if (patEvents.size() > 0) {
        patEvents.forEach(r -> {
          patEventService.deleteDateByCd(r.getPatEventCd().toString());
        });
        List<PatEvent> hasBbsList = patEvents.stream().filter(x -> x.getBbsCtlNo() != 0).collect(Collectors.toList());
        if (hasBbsList.size() > 0) {
          hasBbsList.forEach(x -> {
            try {
              bbsInfoService.deleteBbs(x.getBbsCtlNo());
            } catch (Exception e) {
              // #9700 イベントログに出るべきではないもの、判読不可能なログがある 20260403 del yangxuewang start
//      e.printStackTrace();
              // #9700 イベントログに出るべきではないもの、判読不可能なログがある 20260403 del yangxuewang end
              // #9700 イベントログに出るべきではないもの、判読不可能なログがある 20260403 add yangxuewang start
              EventLogMessage eventLogMessage = new EventLogMessage();
              eventLogMessage.setLogMessage(ExcetionStackTraceToString(e));
              if (bodyData != null && bodyData.getFacility_cd() != null) {
                eventLogMessage.setFacilityCd(bodyData.getFacility_cd());
              }
              logService.log(LogLevel.ERROR, eventLogMessage, "", LoggingConstant.SERVICE_NAME.FNSI, null);
              // #9700 イベントログに出るべきではないもの、判読不可能なログがある 20260403 add yangxuewang end
              }
          });
        }
      }
      // mod 9273 start
      int delInt = patEventDao.deleteByPatIdAndEventStartDate(bodyData.getFacility_cd(), patId, i.getTreatDate());
      if (delInt + patEvents.size() > 0) {
        patEventService.deleteEventAndBbs(bodyData.getFacility_cd(), patId, i.getTreatDate());
      }
      // mod 9273 end
    });
  }
