  /**
   * データ取得
   *
   * @param bodyData 必要パラメータの記載されたJson文字列
   * @return
   * @throws URISyntaxException
   */
  @PostMapping("/getTreatmentConditionSetting")
  public ResponseEntity<List<TreatmentConditionSetting>> getTreatmentConditionSetting(
    @Validated @RequestBody ApiEntityOrdMain.ValiOrdMedi bodyData, BindingResult validationResult
  ) throws URISyntaxException, JSONException, ArrayIndexOutOfBoundsException {

    // 選択された日付+曜日の処理
    String startDate = bodyData.getStart_date().replaceAll("-", "");
    String endDate = bodyData.getEnd_date().compareTo("") != 0 ? bodyData.getEnd_date().replaceAll("-", "") : null;
    List<Integer> weeksArry = IndicationUtils.getWeekPattern((String) bodyData.getWeeks());

    // クールリストはJSON文字列からJavaリストに変換
    JSONArray kurJson = new JSONArray(bodyData.getInd_kur_cd().toString());
    List<Long> kurList = new ArrayList<Long>();
    for (int i = 0; i < kurJson.length(); i++) {
      kurList.add(Long.parseLong(kurJson.get(i).toString()));
    }

    // 治療方法リストはJSON文字列からJavaリストに変換
    JSONArray treatJson = new JSONArray(bodyData.getInd_treatment_cd().toString());
    List<Integer> treatList = new ArrayList<Integer>();
    for (int i = 0; i < treatJson.length(); i++) {
      int treat = Integer.parseInt(treatJson.get(i).toString());
      treatList.add(treat);
    }

    List<TreatmentConditionSetting> mstTreatmentList = new ArrayList();

    try {
      // 更新対象ordNo List取得
      mstTreatmentList = ordMainService.getTreatmentConditionSetting(
        Long.parseLong(bodyData.getPat_id()),
        bodyData.getFacility_cd(),
        startDate,
        endDate,
        weeksArry,
        treatList,
        kurList
      );

    } catch (Exception e) {
      // #9700 イベントログに出るべきではないもの、判読不可能なログがある 20260403 del yangxuewang start
//      e.printStackTrace();
      // #9700 イベントログに出るべきではないもの、判読不可能なログがある 20260403 del yangxuewang end
      EventLogMessage eventLogMessage = new EventLogMessage();
      // #9700 イベントログに出るべきではないもの、判読不可能なログがある 20260403 mod yangxuewang start
      eventLogMessage.setLogMessage(ExcetionStackTraceToString(e));
      if (bodyData != null && bodyData.getFacility_cd() != null) {
        eventLogMessage.setFacilityCd(bodyData.getFacility_cd());
      }
      // #9700 イベントログに出るべきではないもの、判読不可能なログがある 20260403 mod yangxuewang end
      logService.log(LogLevel.ERROR, eventLogMessage, "", SERVICE_NAME.FNSI, null);
    }

    return new ResponseEntity<>(mstTreatmentList, HttpStatus.OK);
  }
