  /**
   * 指示受け・承認の検索
   *
   * @param searchConditions
   * @return
   * @throws Exception
   */
  @PostMapping("/getOrdSearchResult")
  public ResponseEntity<List<OrdChAp>> getOrdSearchResult(@RequestBody OrdSearchCondition searchConditions)
    throws Exception {
    if (null != searchConditions.getOrdSearchTreatmentCondition()) {
      searchConditions.setSearchType(0);
    } else if (null != searchConditions.getOrdSearchInstCondition()) {
      searchConditions.setSearchType(1);
    }

    try {
      if (searchConditions.getSearchType() == 0) {
        List<OrdChAp> ordList = ordMainService.getOrderByTreatmentCondition(
          searchConditions.getOrdSearchTreatmentCondition(), searchConditions);
        return new ResponseEntity<>(ordList, HttpStatus.OK);
      } else {
        List<OrdChAp> ordList = ordMainService
          .getOrderByInstCondition(searchConditions.getOrdSearchInstCondition(), searchConditions);
        return new ResponseEntity<>(ordList, HttpStatus.OK);
      }
    } catch (Exception e) {
      EventLogMessage eventLogMessage = new EventLogMessage();
      // #9700 イベントログに出るべきではないもの、判読不可能なログがある 20260407 mod yangxuewang start
      eventLogMessage.setLogMessage(ExcetionStackTraceToString(e));
      if (searchConditions != null && searchConditions.getFacilityCd() != null) {
        eventLogMessage.setFacilityCd(searchConditions.getFacilityCd());
      }
      // #9700 イベントログに出るべきではないもの、判読不可能なログがある 20260407 mod yangxuewang end
      logService.log(LogLevel.ERROR, eventLogMessage, "", SERVICE_NAME.FNSI,
        null);
      return new ResponseEntity<>(null, HttpStatus.INTERNAL_SERVER_ERROR);
    }
  }


