  /**
   * JSONObjcetを対象データで更新
   *
   * @param jObj 元データ
   * @param map  追加する情報のmap
   * @return jobj 対象データ追加後のデータ
   */
  /* add by shiyw 2024-02-28 [#10196]ord_mainのデータ定義の修正 --start */
  @Deprecated // This method is outdated and not recommended for use. Please call OrdMainUtil.updateJSONObject()
  /* add by shiyw 2024-02-28 [#10196]ord_mainのデータ定義の修正 --start */
  private JSONObject updateJSONObject(JSONObject jObj, Map<String, ?> map) {
    for (Entry<String, ?> entry : map.entrySet()) {
      jObj.put(entry.getKey(), entry.getValue() == null ? JSONObject.NULL : entry.getValue());
    }
    return jObj;
  }

  /**
   * 指定した階層に対象データを追加する
   *
   * @param base           元データ
   * @param map            変更する情報のmap
   * @param RecursionCount 再帰回数
   * @return responseData 対象データ追加後のデータ
   */
  /* add by shiyw 2024-02-28 [#10196]ord_mainのデータ定義の修正 --start */
  @Deprecated // This method is outdated and not recommended for use. Please call OrdMainUtil.updateRecursionJSONObject()
  /* add by shiyw 2024-02-28 [#10196]ord_mainのデータ定義の修正 --start */
  private String updateRecursionJSONObject(String base, Map<String, ?> map, int RecursionCount) {
    if (base.isEmpty()) {
      return null;
    }
    // 対象データ追加後のデータ格納用
    String responseData = base;
    // データがJSONObjectかJSONArrayかをチェック  どちらにも該当しない場合は、処理を何も行わない
    Object json = new JSONTokener(base).nextValue();
    if (json instanceof JSONObject) {
      // データがJSONObjectの場合以下の処理を実行
      JSONObject obj = new JSONObject(base);
      // 戻り値用データ
      JSONObject responseJobj = new JSONObject();
      // 再帰回数が1より小さい場合、そのまま更新する
      if (1 > RecursionCount) {
        responseJobj = this.updateJSONObject(obj, map);
      } else {
        // jsonキーリスト
        JSONArray objKey = obj.names();
        for (int i = 0; i < objKey.length(); i++) {
          String key = objKey.get(i).toString();
          // 再帰回数を1つ減らし、再帰呼び出しをする
          JSONObject o = new JSONObject(updateRecursionJSONObject(obj.getJSONObject(key).toString(), map, RecursionCount - 1));
          // 対象データを格納したObjectを連想配列として格納
          responseJobj.put(key, this.updateJSONObject(o, map));
        }
      }
      responseData = responseJobj.toString();
    } else if (json instanceof JSONArray) {
      // データがJSONArrayの場合以下の処理を実行
      JSONArray jArr = new JSONArray(base);
      // 戻り値用データ
      JSONArray responseArr = new JSONArray();
      for (int i = 0; i < jArr.length(); i++) {
        // JSONArrayの要素内の指定の階層にデータを追加する
        JSONObject obj = new JSONObject(updateRecursionJSONObject(jArr.get(i).toString(), map, RecursionCount));
        // 対象データを格納したObjectを配列として格納
        responseArr.put(obj);
      }
      responseData = responseArr.toString();
    }
    return responseData;
  }

  /**
   * 条件送信キャンセルリスト取得
   *
   * @param ordMainList 更新対象リスト
   * @return 以下の情報を格納したMap
   * 条件送信確認以降の治療状況のものを取り除いた、更新対象リスト
   * 条件送信キャンセルを行った治療情報リスト
   */
  private Map<String, List<OrdMain>> getDoCancelInfo(List<OrdMain> ordMainList) {
    Map<String, List<OrdMain>> responseInfo = new HashMap<String, List<OrdMain>>();
    // 条件送信キャンセル対象リスト
    List<OrdMain> doCancelList = new ArrayList<OrdMain>();
    // 条件送信以降で更新対象から除去したリスト
    List<OrdMain> removedList = new ArrayList<OrdMain>();
    for (int i = ordMainList.size() - 1; - 1 < i; i--) {
      Integer dialysisState = Integer.parseInt(ordMainList.get(i).getRstDialysisState());
      if (0 != ordMainList.get(i).getIndBedCd()) {
        // 条件送信確認後
        if (1 == dialysisState || 2 == dialysisState) {
          doCancelList.add(ordMainList.get(i));
        }
        // 条件送信確認後の場合、更新対象から取り除く
        if (dialysisState >= 3) {
          removedList.add(ordMainList.get(i));
          ordMainList.remove(i);
        }
      }
    }

    responseInfo.put("ordMainList", ordMainList);
    responseInfo.put("doCancelList", doCancelList);
    responseInfo.put("removedList", removedList);

    return responseInfo;
  }

