  @PutMapping("/updateOrdAdditionInfo")
  public ResponseEntity<Void> updateAddInfoById(@RequestBody OrdAdditionInfoRequest request) {
    try {
      List<AdditionInfo> checkList = patMainDao.selectAdditionInfo(request.getFacilityCd(), request.getPatId());
      Boolean patFlg = true;
      List<OrdMainAdditionInfo> ordList = new ArrayList<OrdMainAdditionInfo>();
      if (request.getAdditionInfo().size() > 0) {
        for (OrdMainAdditionInfo item : request.getAdditionInfo()) {
          patFlg = true;
          for (AdditionInfo checkItem : checkList) {
            if (item.getCd().equals(checkItem.getCd())) {
              patFlg = false;
            }
          }
          OrdMainAdditionInfo ord = new OrdMainAdditionInfo();
          MstAddition addition = mstAdditionDao.selectByAdditionCd(item.getCd());
          ord.setCd(item.getCd());
          ord.setName(item.getName());
          ord.setIs_enable("1");
          ord.setStart_date(item.getStart_date());
          ordList.add(ord);
          if (patFlg) {
            AdditionInfo addItem = new AdditionInfo();
            addItem.setCd(item.getCd());
            String isEnable = "1";
            if (addition.getAdditionClass().equals("12") && !addition.getAdditionKind().equals("1")) {
              // 加算種別：汎用(12) + 登録区分：自動(1)以外
              isEnable = "0";
            }
            addItem.setIs_enable(isEnable);
            DateTimeFormatter fmt =  DateTimeFormatter.ofPattern("yyyy-MM-dd'T'HH:mm:ss.SSSXXX");
            addItem.setReg_date(OffsetDateTime.now(ZoneOffset.UTC).format(fmt));      // NOTE : 現在日時を設定
            addItem.setStart_date(item.getStart_date());
            checkList.add(addItem);
          }
        }
      }

      ObjectMapper mapper = new ObjectMapper();
      String ordJsonStr = "[]";
      if (ordList.size() > 0) {
        ordJsonStr = mapper.writeValueAsString(ordList);
      }
      ordMainService.updateAddInfoById(request.getOrdNo(), ordJsonStr);
      String patJsonStr = "[]";
      if (checkList.size() > 0) {
        patJsonStr = mapper.writeValueAsString(checkList);
      }

      // DB更新ログ出力ロジック wangzuo Start
      String tableName = "pat_main";
      // SQL検索条件
      StringBuffer wheres = new StringBuffer("");
      wheres.append(" WHERE\n");
      wheres.append(" pat_id = " + request.getPatId() + "\n");
      // logCommon設定
      DataUpdateLogCommonNew logCommon = getLogCommon(patMainDao, tableName, wheres, getEventLogMessage());
      // ログ出力カラム情報及び更新前データ情報取得
      boolean setResult = logCommon.setInfo();
      // DB更新ログ出力ロジック wangzuo End

      int updateCount = patMainDao.updateAdditionInfoById(request.getPatId(), patJsonStr);

      // DB更新ログ出力ロジック wangzuo Start
      // 更新後データ取得、差分あれば、log出力
      if (setResult && updateCount > 0) {
        logCommon.updateLog();
      }
      // DB更新ログ出力ロジック wangzuo End

      //del 9480 加算・管理料変更は計算されません gjn start
      //add FNSI-redmine6060 fang start
      //webApiCallCommonUtil.doAutoCalculation(request.getOrdNo());
      // add FNSI-redmine6060 fang end
      //del 9480 加算・管理料変更は計算されません gjn start

      return new ResponseEntity<>(HttpStatus.OK);
    } catch (Exception e) {
      // #9700 イベントログに出るべきではないもの、判読不可能なログがある 20260403 del yangxuewang start
//      e.printStackTrace();
      // #9700 イベントログに出るべきではないもの、判読不可能なログがある 20260403 del yangxuewang end
      EventLogMessage eventLogMessage = new EventLogMessage();
      // #9700 イベントログに出るべきではないもの、判読不可能なログがある 20260403 mod yangxuewang start
      eventLogMessage.setLogMessage(ExcetionStackTraceToString(e));
      if (request != null && request.getFacilityCd() != null) {
        eventLogMessage.setFacilityCd(request.getFacilityCd());
      }
      // #9700 イベントログに出るべきではないもの、判読不可能なログがある 20260403 mod yangxuewang end
      logService.log(LogLevel.ERROR, eventLogMessage, "", SERVICE_NAME.FNSI, null);
      return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
    }
  }

