  /**
   * 治療方法による治療条件設定使用チェック
   *
   * @param treatCondSetting 治療方法設定
   * @param treatKey         治療条件項目番号
   * @return 使用フラグ
   */
  private Boolean checkTreatCondIsUse(JSONArray treatCondSetting, String treatKey) {
    for (int i = 0; i < treatCondSetting.length(); i++) {
      JSONArray items = treatCondSetting.getJSONObject(i).getJSONArray("items");
      for (int j = 0; j < items.length(); j++) {
        if (
          items.getJSONObject(j).get("ctl_no").equals(treatKey) &&
            items.getJSONObject(j).get("is_use").equals("0")
        ) {
          return false;
        }
      }
    }

    return true;
  }

  /**
   * 更新された予定一覧を整形して返却する
   *
   * @param facilityCd 施設コード
   * @param updateMode 更新モード
   * @param ordNoList  オーダー番号リスト
   * @return updatedOrdList 更新された予定一覧
   * @throws Exception
   */
  // mod #7235 2022-06-13 他のスケジュールと重複してベッド未登録となった際のイベントが作成されない 孟堅　start
  //　 @PostMapping("/getProcessOrdSchedule/{facilityCd}/{updateMode}")
  //  public ResponseEntity<List<String>> getProcessOrdSchedule(
  //    @PathVariable String facilityCd,
  //    @PathVariable String updateMode,
  //    @RequestBody List<Long> ordNoList) throws Exception {
  @PostMapping("/getProcessOrdSchedule/{facilityCd}/{updateMode}")
  public ResponseEntity<List<String>> getProcessOrdSchedule(
    @PathVariable String facilityCd,
    @PathVariable String updateMode,
    @RequestBody List<Long> ordNoList,
    @AuthenticationPrincipal NtssUser ntssUser) throws Exception {
    // mod #7235 2022-06-13 他のスケジュールと重複してベッド未登録となった際のイベントが作成されない 孟堅　end
    try {
      // スケジュールリストの取得
      List<OrdScheduleCustom> ordScheduleList = ordMainService.getOrdScheduleByOrdNoList(facilityCd, ordNoList);
      // pat_idリストの作成
      List<Long> patIdList = new ArrayList<>();
      for (int i = 0; i < ordScheduleList.size(); i++) {
        patIdList.add(ordScheduleList.get(i).getPatId());
      }
      // pat_idリストから患者情報の取得
      List<PatPersonalMain> patList = patInfoService.getPatListName(patIdList, facilityCd);

      List<String> updatedOrdList = new ArrayList<>();
      for (OrdScheduleCustom ordSch : ordScheduleList) {

        // スケジュール情報の作成
        String scheduleInfo = "";

        // 日付の整形 yyyyMMdd → yyyy/MM/dd
        String treatDate = ordSch.getTreatDate();
        String year = treatDate.substring(0, 4);
        String month = treatDate.substring(4, 6);
        String day = treatDate.substring(6);
        String treatDateFormatted = year + "/" + month + "/" + day;
        scheduleInfo = scheduleInfo + treatDateFormatted;

        // 曜日の整形
        Short treatWeek = ordSch.getTreatWeek();
        Optional<Week> enumWeek = Week.valueOf(treatWeek);
        String treatWeekFormatted = "";
        if (enumWeek.isPresent()) {
          treatWeekFormatted = "(" + enumWeek.get().getText() + ")";
        }
        scheduleInfo = scheduleInfo + treatWeekFormatted;

        // クール名称を設定
        String kurName = ordSch.getKurName();
        scheduleInfo = scheduleInfo + kurName;

        if (updateMode.equals("1")) {
          // 対象患者情報を絞り込み
          List<PatPersonalMain> targetPat = patList.stream()
            .filter((pat) -> {
              return pat.getPat_id().equals(ordSch.getPatId());
            }).collect(Collectors.toList());
          if (targetPat.size() > 0) {
            scheduleInfo = scheduleInfo + " " + targetPat.get(0).getPat_last_name() + " " + targetPat.get(0).getPat_first_name();
            //mod #7235 2022-06-19 他のスケジュールと重複してベッド未登録となった際のイベントが作成されない 孟堅　start
            //add #7235 2022-06-13 他のスケジュールと重複してベッド未登録となった際のイベントが作成されない 孟堅　start
            //  sendCreateJournalApi(facilityCd,ordSch.getPatId(),ordSch.getOrdNo(),ordSch.getTreatDate(),ntssUser.getUserId(),ntssUser);
            //add #7235 2022-06-13 他のスケジュールと重複してベッド未登録となった際のイベントが作成されない 孟堅　end
            //mod #7235 2022-06-19 他のスケジュールと重複してベッド未登録となった際のイベントが作成されない 孟堅　start
          }
        }
        //add #7235 2022-06-19 他のスケジュールと重複してベッド未登録となった際のイベントが作成されない 孟堅　start
        //mod 7068 2023-1-4 患者経過総合ビューアで曜日パターン変更すると変更前の削除イベント・変更後の新規イベントが正しく作成されない 張 start
//        sendCreateJournalApi(facilityCd, ordSch.getPatId(), ordSch.getOrdNo(), ordSch.getTreatDate(), ntssUser);
//        if (!updateMode.equals("3")) {
//          sendCreateJournalApi(facilityCd, ordSch.getPatId(), ordSch.getOrdNo(), ordSch.getTreatDate(), ntssUser);
//        }
//            mod 8260 2023-02-27 患者経過総合ビューアで治療方法を変更すると不要な連携イベントが作成される 張 end
        //mod 7068 2023-1-4 患者経過総合ビューアで曜日パターン変更すると変更前の削除イベント・変更後の新規イベントが正しく作成されない 張 start
        //add #7235 2022-06-19 他のスケジュールと重複してベッド未登録となった際のイベントが作成されない 孟堅　end
        updatedOrdList.add(scheduleInfo);
      }
      return new ResponseEntity<>(updatedOrdList, HttpStatus.OK);
    } catch (Exception e) {
      // #9700 イベントログに出るべきではないもの、判読不可能なログがある 20260403 del yangxuewang start
//      e.printStackTrace();
      // #9700 イベントログに出るべきではないもの、判読不可能なログがある 20260403 del yangxuewang end
      EventLogMessage eventLogMessage = new EventLogMessage();
      // #9700 イベントログに出るべきではないもの、判読不可能なログがある 20260403 mod yangxuewang start
      eventLogMessage.setLogMessage(ExcetionStackTraceToString(e));
      if (facilityCd != null) {
        eventLogMessage.setFacilityCd(facilityCd);
      }
      // #9700 イベントログに出るべきではないもの、判読不可能なログがある 20260403 mod yangxuewang end
      logService.log(LogLevel.ERROR, eventLogMessage, "", SERVICE_NAME.FNSI, null);
      return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
    }
  }

