  /**
   * 新規予定作成の場合、計算材料保持テーブルの登録
   *
   * @param conditions 条件
   * @return 登録結果
   */
  @PostMapping("/ord_material_save")
  public ResponseEntity<?> insertOrdSupplies(
    @Validated @RequestBody ApiEntityOrdMain.ValiOrdMaterialSave conditions
  ) {

    /* add by zhaohan 2022-12-12 [6118] 定期予定発行、予定中止、治療指示変更に時間がかかる。 --start */
    MasterCacheHandler masterCacheHandler = MasterCacheHandler.get();
    /* add by zhaohan 2022-12-12 [6118] 定期予定発行、予定中止、治療指示変更に時間がかかる。 --end */
    List<MstMedicine> mstMedicines = this.selectMedicinesByFactoryId(conditions.getFacility_cd());
    // 予定作成の場合
    if (conditions.getSpecies() == 1) {
      // 治療方法セット取得
      List<MstTreatmentSet> listMstTreatSet = mstInfoService.findMstTreatmentSetByCd(Integer.parseInt(conditions.getTreatment_set_cd()));
      // 指示：治療条件情報Array
      String buf = listMstTreatSet.get(0).getIndCondInfo();
      JSONObject setCond = new JSONObject(buf);
      // 治療日で、計算材料保持テーブルデータを追加する
      for (String baseDate : conditions.getSupplies_base_date()) {
        // データ基準日を設定する
        conditions.setBase_date(baseDate);
        // ord_noの取得
        List<String> ordNoList = ordMainService.selectOrdNo(
          conditions.getPat_id(),
          conditions.getFacility_cd(),
          baseDate
        );
        // データ基準番号を設定する
        conditions.setSupplies_base_no(ordNoList.get(0));

        // 結果フラグ
        List<OrdMaterialSave> ordMaterialSaveList = new ArrayList<>();
        /* modify by zhaohan 2022-12-12 [6118] 定期予定発行、予定中止、治療指示変更に時間がかかる。 --start */
        // 治療条件值的设定
        ordMaterialSaveList.addAll(this.indCondValueSetting(conditions, setCond, masterCacheHandler, null));
        /* modify by zhaohan 2022-12-12 [6118] 定期予定発行、予定中止、治療指示変更に時間がかかる5。 --end */

        // 投与薬剤情報值的设定
        buf = listMstTreatSet.get(0).getIndMediInfo();
        JSONArray setMedi = new JSONArray(buf);
        ordMaterialSaveList.addAll(this.indMediValueSetting(conditions, setMedi,mstMedicines));

        // 医療材料情報值的设定
        buf = listMstTreatSet.get(0).getIndEquipInfo();
        JSONArray setEquip = new JSONArray(buf);
        /* modify by shiyw 2023-01-03 [6118] add parameter "masterCacheHandler" to avoid repeated querying of the database ,see this.selectMedicinesByFactoryId() --start */
        ordMaterialSaveList.addAll(this.indEquipValueSetting(conditions, setEquip,masterCacheHandler));
        /* modify by shiyw 2023-01-03 [6118] add parameter "masterCacheHandler" to avoid repeated querying of the database ,see this.selectMedicinesByFactoryId() --end */
        if(!ordMaterialSaveList.isEmpty()){
          ordMaterialSaveService.insertBatch(ordMaterialSaveList);
        }
      }
      return new ResponseEntity<>(1, HttpStatus.OK);

      // 予定コーピの場合
    } else if (conditions.getSpecies() == 2) {
      // 結果フラグ
      List<OrdMaterialSave> ordMaterialSaveList = new ArrayList<>();
      // データ基準日設定
      String baseDate = conditions.getBase_date().replaceAll("-", "");
      conditions.setBase_date(baseDate);
      // 治療情報を取得する
      OrdMain ordMain = ordMainService.selectByOrdNo(Long.parseLong(conditions.getOriginal_base_no()));
      // ord_noの取得
      List<String> ordNoList = ordMainService.selectOrdNo(
        conditions.getPat_id(),
        conditions.getFacility_cd(),
        baseDate
      );
      // データ基準番号を設定する
      conditions.setSupplies_base_no(ordNoList.get(0));
      // 治療条件情報
      // mod bug 6968 修正 chen start
      JSONObject indCondInfo = null == ordMain.getIndCondInfo() ?
        new JSONObject() :
        new JSONObject(ordMain.getIndCondInfo());
      /* modify by zhaohan 2022-12-12 [6118] 定期予定発行、予定中止、治療指示変更に時間がかかる。 --start */
      // result = this.indCondValueSetting(conditions, indCondInfo);
      ordMaterialSaveList.addAll( this.indCondValueSetting(conditions, indCondInfo,  masterCacheHandler, null) );
      /* modify by zhaohan 2022-12-12 [6118] 定期予定発行、予定中止、治療指示変更に時間がかかる5。 --end */
      // mod bug 6968 修正 chen end
      // 投与薬剤情報
      if(!ObjectUtils.isEmpty(ordMain.getIndMediInfo())) { // add by shiyw 2024-03-28 #10196 ord_mainのデータ定義の修正:OrdMain.equipInfo/mediInfo/IndCommentInfoがnullの場合を考える
        ordMaterialSaveList.addAll( this.indMediValueSetting(conditions, new JSONArray(ordMain.getIndMediInfo()),mstMedicines) );
      }
      // 医療材料情報
      /* modify by shiyw 2023-01-03 [6118] add parameter "masterCacheHandler" to avoid repeated querying of the database ,see this.selectMedicinesByFactoryId() --start */
      //result = this.indEquipValueSetting(conditions, new JSONArray(ordMain.getIndEquipInfo()));
      if(!ObjectUtils.isEmpty(ordMain.getIndEquipInfo())) { // add by shiyw 2024-03-28 #10196 ord_mainのデータ定義の修正:OrdMain.equipInfo/mediInfo/IndCommentInfoがnullの場合を考える
        ordMaterialSaveList.addAll( this.indEquipValueSetting(conditions, new JSONArray(ordMain.getIndEquipInfo()),masterCacheHandler) );
      }
      /* modify by shiyw 2023-01-03 [6118] add parameter "masterCacheHandler" to avoid repeated querying of the database ,see this.selectMedicinesByFactoryId() --end */
      ordMaterialSaveService.insertBatch(ordMaterialSaveList);
      return new ResponseEntity<>(1, HttpStatus.OK);
    }
    return new ResponseEntity<>(- 1, HttpStatus.INTERNAL_SERVER_ERROR);
  }

  /* add by chamaojia 2023-04-11 [6118] プライベートなデータ処理方法の追加 --start */
  // service層から移動してきた、serviceにおける切断面に性能問題がある
  private OrdMaterialSave ordMaterialCreate(ApiEntityOrdMain.ValiOrdMaterialSave conditions) {
    OrdMaterialSave oms = new OrdMaterialSave();
    // 施設コード
    oms.setFacilityCd(conditions.getFacility_cd());
    // 患者ID
    oms.setPatId(Long.parseLong(conditions.getPat_id()));
    // データ基準日
    oms.setSuppliesBaseDate(conditions.getBase_date());
    // データ基準番号
    oms.setSuppliesBaseNo(Long.parseLong(conditions.getSupplies_base_no()));
    // データ発生元区分
    oms.setSuppliesSourceClass(String.valueOf(conditions.getSupplies_source_class()));
    // 物品区分
    oms.setSuppliesClass(conditions.getSupplies_class());
    // 物品コード
    oms.setSuppliesCd(conditions.getSupplies_cd());
    // 調整薬剤コード
    oms.setMedicineMixCd(conditions.getMedicine_mix_cd());
    // 分類コード
    oms.setClassCd(conditions.getClass_cd());
    // 指示・実績区分
    oms.setIndRstClass(conditions.getInd_rst_class());
    // 指示・実績値
    oms.setIndRstValue(conditions.getInd_rst_value());
    // レセ値
    oms.setReceiptValue(conditions.getReceipt_value());
    // 確定フラグ
    oms.setIsConfirm(conditions.getIs_confirm());
    // 登録日時 and 更新日時
    Timestamp tm = Timestamp.from(Instant.now());
    oms.setRegDate(tm);
    oms.setUpDate(tm);
    return oms;
  }

  // mod #7475 コンバートしたord_mainにデータが正常な形でコンバートされていない dou start
  //private HashMap<String, String> indCondJsonToMap(JSONObject setCond) {
  //HashMap<String, String> setCondMap = new HashMap<>();
  private HashMap<String, Object> indCondJsonToMap(JSONObject setCond) {
    HashMap<String, Object> setCondMap = new HashMap<>();
    // mod #7475 コンバートしたord_mainにデータが正常な形でコンバートされていない dou end
    String[] keyArr = {"13","5","6","7","8","12","9","10","11","15","19","22","25","26","28","17"};
    // mod 6824 ord_material_saveテーブルへのデータ格納が正しくない 関  end
    for(String key : keyArr){
      if(setCond.has(key)){
        JSONObject jsonObject = setCond.getJSONObject(key);
        String value = jsonObject.get("value").toString();
        setCondMap.put(key,value);
        if("25".equals(key)){
          //upd 新規予定治療方法の報告ミス 修正 20230705 ztc start
          if(!jsonObject.isNull("medicine_type")){
            // mod #7475 コンバートしたord_mainにデータが正常な形でコンバートされていない dou start
            //String medicineType = jsonObject.get("medicine_type").toString();
            Integer medicineType = Integer.parseInt(jsonObject.get("medicine_type").toString());
            // mod #7475 コンバートしたord_mainにデータが正常な形でコンバートされていない dou end
            setCondMap.put("25->medicine_type", medicineType);
          }else {
            setCondMap.put("25->medicine_type", null);
          }
          //upd 新規予定治療方法の報告ミス 修正 20230705 ztc end
        }
      }
    }
    return setCondMap;
  }
