  private List<MstMedicine> selectMedicinesByFactoryId(String facilityCd){
    MstMedicine mstMedicineI = new MstMedicine();
    mstMedicineI.setFacilityCd(facilityCd);
    mstMedicineI.setIsDel("0");
    SelectOptions selectOptions = SelectOptions.get();
    return mstMedicineDao.selectAll(selectOptions, mstMedicineI);
  }

