  /**
   * 計算材料情報を取得
   *
   * @param bodyData 必要パラメータの記載されたJson文字列
   * @return
   * @throws URISyntaxException
   */
  @PostMapping("/getOrdMaterialSave")
  public ResponseEntity<List<OrdMaterialSaveCommon>> getOrdMaterialSave(
    @Validated @RequestBody ApiEntityOrdMain.ValiOrdMaterialSaveGraph bodyData, BindingResult validationResult
  ) throws URISyntaxException {// 検査依頼結果の削除処理
    try {
      List<OrdMaterialSaveCommon> listRet = ordMaterialSaveService.getOrdMaterialSaveForCommon(
        bodyData.getFacility_cd(),
        bodyData.getPat_id(),
        bodyData.getSupplies_base_date_begin(),
        bodyData.getSupplies_base_date_end()
      );
      if("0".equals(bodyData.getShareMode())) {
        List<ShrPatInfo> shrPatInfos = shrPatInfoService.selectShrPatInfoByPatId(bodyData.getPat_id(), bodyData.getFacility_cd());
        if(!CollectionUtils.isEmpty(shrPatInfos)) {
          for(ShrPatInfo shrPatInfo : shrPatInfos) {
            List<OrdMaterialSaveCommon> tempRet = ordMaterialSaveService.getOrdMaterialSaveForCommon(
              shrPatInfo.getFromFacilityCd(),
              shrPatInfo.getFromPatId(),
              bodyData.getSupplies_base_date_begin(),
              bodyData.getSupplies_base_date_end()
            );
            listRet.addAll(tempRet);
          }
        }
      }
      if (null == listRet) {
        // 失敗した場合、内部エラー処理
        return new ResponseEntity<>(null, HttpStatus.INTERNAL_SERVER_ERROR);
      }
      return new ResponseEntity<>(listRet, HttpStatus.OK);
    } catch (Exception e) {
      // #9700 イベントログに出るべきではないもの、判読不可能なログがある 20260403 del yangxuewang start
//      e.printStackTrace();
      // #9700 イベントログに出るべきではないもの、判読不可能なログがある 20260403 del yangxuewang end
      EventLogMessage eventLogMessage = new EventLogMessage();
      // #9700 イベントログに出るべきではないもの、判読不可能なログがある 20260403 mod yangxuewang start
      eventLogMessage.setLogMessage(ExcetionStackTraceToString(e));
      if (bodyData != null && bodyData.getFacility_cd() != null) {
        eventLogMessage.setFacilityCd(bodyData.getFacility_cd());
      }
      // #9700 イベントログに出るべきではないもの、判読不可能なログがある 20260403 mod yangxuewang end
      logService.log(LogLevel.ERROR, eventLogMessage, "", SERVICE_NAME.FNSI, null);
      return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
    }
  }
