  /**
   * 治療予定変更 with 治療方法セットコード
   *
   * @param bodyData 必要パラメータの記載されたJson文字列
   * @return
   * @throws URISyntaxException
   * @throws ParseException
   * @throws JSONException
   */
  @PostMapping("updatetByTreatSetCd2")
  public ResponseEntity<String> updatetByTreatSetCdOptimize2(
    @Validated @RequestBody ApiEntityOrdMain.ValiCreateTreatPlan bodyData, BindingResult validationResult,
    @AuthenticationPrincipal NtssUser ntssUser
  ) throws Exception {
    EventLogMessage eventLogMessage = new EventLogMessage();
    eventLogMessage.setLogMessage("REST request to updatetByTreatSetCd2 OrdMain : " + bodyData.getTreatment_set_cd() + bodyData.getUp_date());
    logService.log(LogLevel.DEBUG, eventLogMessage, "", SERVICE_NAME.FNSI, null);
    eventLogMessage = new EventLogMessage();
    eventLogMessage.setLogMessage("治療方法コード: " + bodyData.getInd_treatment_cd()
      + " クールコード: " + bodyData.getInd_kur_cd()
      + " 終了日有無: " + bodyData.getIs_deadline()
      + " 更新対象治療方法: " + bodyData.getInd_treatment_cd()
      + " 更新対象クール: " + bodyData.getInd_kur_cd()
      + " 治療種別: " + bodyData.getTreat_type()
      + " 更新日時: " + bodyData.getUp_date()
      + " 治療日リスト: " + bodyData.getTreatDays()
      + " 曜日パターン: " + bodyData.getWeek_pattern()
    );
    // バリデーションエラーチェック
    if (validationResult.hasErrors()) {
      // バリデーションエラーが発生した場合はパラメータ異常扱い
      eventLogMessage = new EventLogMessage();
      eventLogMessage.setLogMessage("result:" + validationResult);
      logService.log(LogLevel.INFO, eventLogMessage, "", SERVICE_NAME.FNSI, null);
      for (ObjectError error : validationResult.getFieldErrors()) {
        eventLogMessage = new EventLogMessage();
        eventLogMessage.setLogMessage("error:" + error.getDefaultMessage());
        logService.log(LogLevel.ERROR, eventLogMessage, "", SERVICE_NAME.FNSI, null);
      }
      // 引数は、ボディデータ、ヘッダーデータ、ステータス
      return new ResponseEntity<>("パラメータエラー", null, HttpStatus.BAD_REQUEST);
    }
    logService.log(LogLevel.INFO, eventLogMessage, "", SERVICE_NAME.FNSI, null);

    InvokeResult<Map<String,List>> invokeResult = checkAndUpdate(bodyData,ntssUser);

    Map<String,List> resultMap = invokeResult.getData();

    List<OrdMain> callNextPatOrdMainList = (ArrayList<OrdMain>) resultMap.get("ordMainList");

    //mod #10412 次患者更新関連全体見直し対応 朴 start
    // 次患者
    // treatmentService.callSetNextPatInfo(bodyData.getFacility_cd(),callNextPatOrdMainList);
    nextPatService.CallNextPatChange(bodyData.getFacility_cd(),callNextPatOrdMainList);
    //mod #10412 次患者更新関連全体見直し対応 朴 end

    JSONObject data = new JSONObject("{}");

    // mod #12465 同患者同日同治療方法同クールの使用制限をしてもメッセージがでない zkm start
    data.put("msglist", resultMap.get("msglist"));
    // mod #12465 同患者同日同治療方法同クールの使用制限をしてもメッセージがでない zkm end
    // add 11061 治療方法変更治療時間が長すぎて他の予定と衝突する 関 start
    data.put("duplicatedOrdNoList",resultMap.get("duplicatedOrdNoList"));
    // add 11061 治療方法変更治療時間が長すぎて他の予定と衝突する 関 end
    return new ResponseEntity<>(data.toString(), null, HttpStatus.OK);
  }

  private InvokeResult<Map<String,List>> checkAndUpdate(ApiEntityOrdMain.ValiCreateTreatPlan bodyData, NtssUser ntssUser) throws Exception {
    // 戻り値情報
    List<JournalCreateRequestPayload> ctlNoList = new ArrayList<>();
    List<MstTreatmentSet> listMstTreatSet = mstInfoService.findMstTreatmentSetByCd(Integer.parseInt(bodyData.getTreatment_set_cd()));
    PatMain patMain = patMainDao.selectById(Long.parseLong(bodyData.getPat_id()));
    InvokeResult<Map<String,List>> invokeResult = new InvokeResult<>();
    ArrayList<String> msgList = new ArrayList<>();
    Map<String,List> resultData = new HashMap<>();
    ArrayList<String> error = new ArrayList<>();

    // スケジュール延長処理中の場合、予定作成を中止する
    // mod #10712 日次スケジュール自動延長処理の除外考慮修正 zkm start
//    if (("1").equals(patMain.getSch_ext_status())) {
    if (("1").equals(patMain.getSch_ext_status()) && Boolean.FALSE.toString().equals(bodyData.getIs_deadline())) {
      // mod #10712 日次スケジュール自動延長処理の除外考慮修正 zkm end
      msgList.add("22020004");
      // mod #12465 同患者同日同治療方法同クールの使用制限をしてもメッセージがでない zkm start
//      resultData.put("msgList", msgList);
      resultData.put("msglist", msgList);
      // mod #12465 同患者同日同治療方法同クールの使用制限をしてもメッセージがでない zkm end
      invokeResult.success(resultData);
      return invokeResult;
    }
    if (0 != Integer.parseInt(bodyData.getTreat_method_flag())) {
      if (1 != listMstTreatSet.size()) {
        //引数は、ボディデータ,ヘッダーデータ,ステータス
        error.add("治療方法セットマスタ参照エラー");
        resultData.put("error", error);
        invokeResult.success(resultData);
        return invokeResult;
      }
      Timestamp bodyUpdate = new Timestamp(new SimpleDateFormat("yyyy-MM-dd'T'HH:mm:ss.SSSZ").parse(bodyData.getUp_date()).getTime());
      if (!bodyUpdate.equals(listMstTreatSet.get(0).getUpDate())) {
        HttpStatus status = HttpStatus.BAD_REQUEST;
        //引数は、ボディデータ,ヘッダーデータ,ステータス
        error.add("排他エラー");
        resultData.put("error", error);
        invokeResult.success(resultData);
        return invokeResult;
      }
    }
    // 投薬最新識別番号の取得
    // mod #12471 投薬最新識別番号の設定 zkm start
//    long mediInfoNo = ordMainDao.selectIndMediInfoNo(bodyData.getFacility_cd(), bodyData.getPat_id());
    Long mediInfoNo = ordMainDao.lockMaxIndMediInfoNo(bodyData.getFacility_cd(), bodyData.getPat_id());
    if (mediInfoNo == null) {
      mediInfoNo = Long.parseLong("-1");
    }
    // mod #12471 投薬最新識別番号の設定 zkm end
    if (1 == Integer.parseInt(bodyData.getTreat_method_flag())) {
      // 指示：投与薬剤情報
      /* #10757 mod コンバートされた治療方法セットで指示が作成できない 2024-06-26 卓 start */
      // JSONArray setMedi = new JSONArray(listMstTreatSet.get(0).getIndMediInfo());
      JSONArray setMedi = new JSONArray(ObjectUtils.isEmpty(listMstTreatSet.get(0).getIndMediInfo())? "[]" : listMstTreatSet.get(0).getIndMediInfo());
      /* #10757 mod コンバートされた治療方法セットで指示が作成できない 2024-06-26 卓 end */
      // mod #12471 投薬最新識別番号の設定 zkm start
//      // 識別番号が取得する場合
//      if (mediInfoNo >= 0) {
//        // 投薬最新識別番号の更新
//        ordMainDao.updateIndMediInfoNo(bodyData.getFacility_cd(), bodyData.getPat_id(), mediInfoNo + setMedi.length());
//        // 識別番号が取得しない場合
//      } else {
//        // 投薬最新識別番号の登録
//        ordMainDao.insertIndMediInfoNo(bodyData.getFacility_cd(), bodyData.getPat_id(),setMedi.length());
//      }
      Timestamp nowTs = Timestamp.from(Instant.now());
      ordMainDao.updatePatMedicineNo(
        new MedicineLatestNo(bodyData.getFacility_cd(), Long.valueOf(bodyData.getPat_id()), setMedi.length(), nowTs, nowTs
          , AdminWebConstant.FlagType.FLAG_ON, AdminWebConstant.FlagType.FLAG_OFF)
      );
      // mod #12471 投薬最新識別番号の設定 zkm end
    }

    journalService.callCreateJournalForCtrNo(ctlNoList);
    return ordMainService.updatetByTreatSetCdOptimizeImpl(bodyData, ntssUser, ctlNoList, mediInfoNo);
  }
