  /**
   * 治療法変更最初の治療日のdw取得
   *
   * @param bodyData 治療日条件の検索
   * @return
   * @throws URISyntaxException
   */
  //mod #12660 【securify】SQLインジェクション(High) まとめ zrx start
  @PostMapping("/getTreatDateDw")
  public ResponseEntity<String> getTreatDateDw(@Valid @RequestBody ApiEntityOrdMain.ValiSearchTreatDateDw bodyData,@AuthenticationPrincipal NtssUser ntssUser
  ) throws Exception {
  //mod #12660 【securify】SQLインジェクション(High) まとめ zrx end

    // mod 10742 治療方法変更時に治療方法セットを使うと、DWと同じに変更されてしまう 関  start
    JSONObject result = new JSONObject();

    String dateFrom = ((null != bodyData.getInd_start_date()) && (false == "".equals(bodyData.getInd_start_date()))) ? bodyData.getInd_start_date().replaceAll("-", "") : null;

    // 曜日パターン情報加工
    List<Integer> weekPattern = new ArrayList<Integer>();
    if ((null != bodyData.getWeek_pattern()) && (false == "".equals(bodyData.getWeek_pattern()))) {
      weekPattern = IndicationUtils.getWeekPattern(bodyData.getWeek_pattern());
      if (null == weekPattern) {
        return new ResponseEntity<>(null, HttpStatus.BAD_REQUEST);
      }
    }
    Long ordNo = bodyData.getOrd_no() != null ? Long.parseLong(bodyData.getOrd_no()) : null;
    Boolean isIndFlag = ordNo != null ? false : true;

    // 治療方法リスト
    List<Integer> treatmentCdList = this.getValueList(bodyData.getInd_treatment_cd());
    // クールリスト
    List<Long> kurCdList = this.getLongList(bodyData.getInd_kur_cd());

    OrdMain ordMain = new OrdMain();
    ordMain = ordMainService.getTreatDate(
      Long.parseLong(bodyData.getPat_id()),
      bodyData.getFacility_cd(),
      dateFrom,
      weekPattern,
      treatmentCdList,
      kurCdList,
      isIndFlag
    );

    List<PatUniquePhysicalInfo> physicalInfo = new ArrayList<>();
    String dw = "";
    String targetWeight = "";
    // mod #11408 特殊浄化の治療方法セットマスタで治療方法の変更できない zkm start
//    if (ordMain != null) {
    if (ordMain != null && !StringUtils.isEmpty(ordMain.getIndCondInfo())) {
      // mod #11408 特殊浄化の治療方法セットマスタで治療方法の変更できない zkm end
      JSONObject indCondInfo = new JSONObject(ordMain.getIndCondInfo());
      if (indCondInfo.has("3") && !indCondInfo.getJSONObject("3").isNull("value")) {
        targetWeight = indCondInfo.getJSONObject("3").get("value").toString();
      }
    }
    if (ordMain != null && "0".equals(ordMain.getRstDialysisState())) {
      if (ordMain.getTreatDate() != null) {
        physicalInfo = patUniqueDao.selectDwByTreatDate(Long.parseLong(bodyData.getPat_id()), bodyData.getFacility_cd(), ordMain.getTreatDate() );
        if (physicalInfo.size() >0 && physicalInfo.get(0).getDw() != null) {
          dw = physicalInfo.get(0).getDw().toString();
        }
      }
    }else if(ordMain != null && !"0".equals(ordMain.getRstDialysisState())) {
      if (ordMain.getIndDw() != null){
        dw = ordMain.getIndDw().toString();
      }
    }
    if (dw == "") {
      physicalInfo = patUniqueDao.selectDwByTreatDate(Long.parseLong(bodyData.getPat_id()), bodyData.getFacility_cd(), dateFrom);
      if (physicalInfo.size() > 0 && physicalInfo.get(0).getDw() != null) {
        dw = physicalInfo.get(0).getDw().toString();
      }
    }
    result.put("dw", dw);
    result.put("targetWeight", targetWeight);

    return new ResponseEntity<>(result.toString(), HttpStatus.OK);
    // mod 10742 治療方法変更時に治療方法セットを使うと、DWと同じに変更されてしまう 関  end
  }
