  // add 11495 条件送信済みのオンライン治療で透析液と透析液使用数を変更すると補液使用数の値まで変更される。 関 start

  private void processDialysate(JSONObject condInfo, JSONObject indCondDBJson, JSONObject jsonObject1, OrdMain ordMainObject, String indTreatCondIvMode) {
    boolean hasDialysisState = ordMainObject.getRstDialysisState() != null && !"0".equals(ordMainObject.getRstDialysisState());

    if (!(condInfo.has(T_I_DIALYSES.getItemCode()) || condInfo.has(T_I_IV_COUNT.getItemCode()) ||
      condInfo.has(T_I_IV.getItemCode()))) {
      return;
    }

    if (condInfo.has(T_I_DIALYSES.getItemCode())) {
      JSONObject dialysateJson = new JSONObject(condInfo.optJSONObject("15").toString());
      JSONObject dialysateNumJson = indCondDBJson.optJSONObject("17");
      JSONObject fluidNumJson = indCondDBJson.optJSONObject("22");

      // 透析液->補液連動処理
      if (!isNullValue(dialysateJson.optString("value", "")) && indCondDBJson.has("19")) {
        jsonObject1.put("19", dialysateJson);
      } else {
        if (indCondDBJson.has("19")) {
          if (!hasDialysisState) {
            dialysateJson.remove("unit");
            dialysateJson.remove("value_name_1");
          }
          dialysateJson.put("value_name_1", JSONObject.NULL);
          jsonObject1.put("19", dialysateJson);
        }
      }

      if (hasDialysisState) {
        // 透析液->透析液使用数連動処理
        if (condInfo.has(T_I_DIALYSES.getItemCode()) && !condInfo.has(T_I_DIALYSES_AMOUNT.getItemCode())
          && indCondDBJson.has(T_I_DIALYSES_AMOUNT.getItemCode())) {
          if (!isNullValue(dialysateJson.optString("value", ""))) {
            MedicineUnitInfo medicineUnitInfo = getMedicineUnitInfo(dialysateJson, ordMainObject);
            dialysateNumJson.put("unit", (medicineUnitInfo.unit != null && !"null".equals(medicineUnitInfo.unit)) ? medicineUnitInfo.unit : JSONObject.NULL);
            jsonObject1.put("17", dialysateNumJson);
          }
        }
        // online透析液->補液使用数連動処理
        if ("onLine".equals(indTreatCondIvMode) && condInfo.has(T_I_DIALYSES.getItemCode())
          && indCondDBJson.has(T_I_IV_COUNT.getItemCode()) && !isNullValue(dialysateJson.optString("value", ""))) {
          MedicineUnitInfo medicineUnitInfo = getMedicineUnitInfo(dialysateJson, ordMainObject);

          if (condInfo.has(T_I_IV_COUNT.getItemCode())) {
            JSONObject fluidNumNewJson = condInfo.optJSONObject("22");
            fluidNumNewJson.put("unit", (medicineUnitInfo.unit != null && !"null".equals(medicineUnitInfo.unit)) ? medicineUnitInfo.unit : JSONObject.NULL);
            jsonObject1.put("22", fluidNumNewJson);
          }else {
            fluidNumJson.put("unit", (medicineUnitInfo.unit != null && !"null".equals(medicineUnitInfo.unit)) ? medicineUnitInfo.unit : JSONObject.NULL);
            jsonObject1.put("22", fluidNumJson);
          }
        }
      } else if ("onLine".equals(indTreatCondIvMode) && indCondDBJson.has("22")
        && condInfo.has(T_I_IV_COUNT.getItemCode())){
        JSONObject fluidNumNewJson = condInfo.optJSONObject("22");
        fluidNumNewJson.remove("unit");
        fluidNumNewJson.remove("value_name_1");
        jsonObject1.put("22", fluidNumNewJson);
      }
    }

    // 補液使用数処理
    if (!condInfo.has(T_I_DIALYSES.getItemCode()) && condInfo.has(T_I_IV_COUNT.getItemCode())
      && "onLine".equals(indTreatCondIvMode) && indCondDBJson.has("22")) {
      JSONObject fluidNumNewJson = condInfo.optJSONObject("22");
      if (!hasDialysisState) {
        fluidNumNewJson.remove("unit");
        fluidNumNewJson.remove("value_name_1");
      }
      jsonObject1.put("22", fluidNumNewJson);
    }
  }

  private void processFluid(JSONObject condInfo, JSONObject indCondDBJson, JSONObject jsonObject1, OrdMain ordMainObject, String indTreatCondIvMode) {
    boolean hasDialysisState = ordMainObject.getRstDialysisState() != null && !"0".equals(ordMainObject.getRstDialysisState());

    if (!(condInfo.has(T_I_IV.getItemCode()) || condInfo.has(T_I_IV_COUNT.getItemCode())
      || condInfo.has(T_I_DIALYSES.getItemCode()))) {
      return;
    }
    // 実績透析液のみを変更する場合の連動透析液使用数の単位処理
    if (hasDialysisState) {
      if (condInfo.has(T_I_DIALYSES.getItemCode()) && !condInfo.has(T_I_DIALYSES_AMOUNT.getItemCode())
        && indCondDBJson.has(T_I_DIALYSES_AMOUNT.getItemCode())) {
        JSONObject dialysateJson = new JSONObject(condInfo.optJSONObject("15").toString());
        JSONObject dialysateNumJson = indCondDBJson.optJSONObject("17");
        MedicineUnitInfo medicineUnitInfo = getMedicineUnitInfo(dialysateJson, ordMainObject);

        if (!isNullValue(dialysateJson.optString("value", ""))) {
          dialysateNumJson.put("unit", (medicineUnitInfo.unit != null && !"null".equals(medicineUnitInfo.unit)) ? medicineUnitInfo.unit : JSONObject.NULL);
          jsonObject1.put("17", dialysateNumJson);
        }
      }
    }

    if (condInfo.has(T_I_IV.getItemCode())) {
      JSONObject fluidJson = new JSONObject(condInfo.optJSONObject("19").toString());

      // 未登録以外の補液変更処理
      if (!isNullValue(fluidJson.optString("value", ""))) {
        MedicineUnitInfo medicineUnitInfo = getMedicineUnitInfo(fluidJson, ordMainObject);

        // 補液変更処理
        if (indCondDBJson.has("19")) {
          if (!hasDialysisState) {
            fluidJson.remove("unit");
            fluidJson.remove("value_name_1");
          }
          jsonObject1.put("19", fluidJson);
        }

        // 実績補液時連動補液使用数のみを変更する単位処理
        if (hasDialysisState) {
          if ("offLine".equals(indTreatCondIvMode) && indCondDBJson.has("22")) {
            if (condInfo.has(T_I_IV_COUNT.getItemCode())) {
              JSONObject fluidNumNewJson = condInfo.optJSONObject("22");

              fluidNumNewJson.put("unit", (medicineUnitInfo.unit != null && !"null".equals(medicineUnitInfo.unit)) ? medicineUnitInfo.unit : JSONObject.NULL);
              jsonObject1.put("22", fluidNumNewJson);
            }else {
              JSONObject fluidNumJson = indCondDBJson.optJSONObject("22");
              fluidNumJson.put("unit", (medicineUnitInfo.unit != null && !"null".equals(medicineUnitInfo.unit)) ? medicineUnitInfo.unit : JSONObject.NULL);
              jsonObject1.put("22", fluidNumJson);
            }
          }
        }else if ("offLine".equals(indTreatCondIvMode) && indCondDBJson.has("22")
          && condInfo.has(T_I_IV_COUNT.getItemCode())){
          JSONObject fluidNumNewJson = condInfo.optJSONObject("22");
          fluidNumNewJson.remove("unit");
          fluidNumNewJson.remove("value_name_1");
          jsonObject1.put("22", fluidNumNewJson);
        }
        // 補液変更未登録処理
      } else {
        if (indCondDBJson.has("19")) {
          if (!hasDialysisState) {
            fluidJson.remove("unit");
            fluidJson.remove("value_name_1");
          }
          jsonObject1.put("19", fluidJson);
        }
      }
    }

    // 補液使用数処理
    if (!condInfo.has(T_I_IV.getItemCode()) && condInfo.has(T_I_IV_COUNT.getItemCode())
      && "offLine".equals(indTreatCondIvMode) && indCondDBJson.has("22")) {
      JSONObject fluidNumNewJson = condInfo.optJSONObject("22");
      if (!hasDialysisState) {
        fluidNumNewJson.remove("unit");
        fluidNumNewJson.remove("value_name_1");
      }
      jsonObject1.put("22", fluidNumNewJson);
    }
  }
  private boolean isNullValue(String value) {
    return value == null || value.trim().isEmpty() || "null".equalsIgnoreCase(value);
  }
  /**
   * 医薬品事業所情報の取得
   */
  private MedicineUnitInfo getMedicineUnitInfo(JSONObject medicineJson, OrdMain ordMainObject) {
    int medicineType = medicineJson.getInt("medicine_type");
    Integer medicineCd = medicineJson.getInt("value");

    if (medicineType == 1) {
      MstMedicine mstMedicine = mstMedicineDao.selectAllByMediCd(medicineCd);
      return new MedicineUnitInfo(mstMedicine.getUnitSecond(), mstMedicine.getUnitDecimalPointSecond());
    } else {
      MstMedicineMix mstMedicineMix = mstMedicineMixDao.selectByCd(ordMainObject.getFacilityCd(), medicineCd);
      return new MedicineUnitInfo(mstMedicineMix.getUnit(), mstMedicineMix.getUnitDecimalPoint());
    }
  }

  /**
   * 医薬品単位情報類
   */
  private static class MedicineUnitInfo {
    String unit;
    Integer unitDecimalPoint;

    MedicineUnitInfo(String unit, Integer unitDecimalPoint) {
      this.unit = unit;
      this.unitDecimalPoint = unitDecimalPoint;
    }
  }

  public void optimizeProcess(JSONObject condInfo, JSONObject indCondDBJson, JSONObject jsonObject1, OrdMain ordMainObject, Integer deviceMode, String indTreatCondIvMode) {
    if (DeviceMode.OHDF.equals(deviceMode) || DeviceMode.OHF.equals(deviceMode) || DeviceMode.I_HDF.equals(deviceMode)) {
      processDialysate(condInfo, indCondDBJson, jsonObject1, ordMainObject, indTreatCondIvMode);
    } else {
      processFluid(condInfo, indCondDBJson, jsonObject1, ordMainObject, indTreatCondIvMode);
    }
  }
