  /**
   *
   *
   * @param
   * @return
   * @throws URISyntaxException
   */
  @PostMapping("/updateWeekPatternInfo2")
  public ResponseEntity<UpdateScheduleListDataResponse> updateWeekPatternInfo2(@Validated @RequestBody ApiEntityOrdMain.ValiWeekPattern bodyData) throws RuntimeException {
    HttpStatus status = HttpStatus.OK;

    UpdateScheduleListDataResponse scheduleResponse = new UpdateScheduleListDataResponse();

    OrdMainWeekPatternResponse changeResponse = new OrdMainWeekPatternResponse();

    EventLogMessage eventLogMessage = new EventLogMessage();

    String facilityCd = bodyData.getFacility_cd();

    // ① WeekPattern を構築する
    WeekPatternResponse weekResponse = buildWeekPatternResponse(bodyData);

    try {
      // ② ord_main pat_treatment_pattern データを取得
      List<TreatmentInstance> treatmentInstanceList =
        weekPatternInfoService.expandAndMergeOrdMainAndPatternToTreatmentInstances(
          weekResponse, null, null,
          new ArrayList<>(), new ArrayList<>(),
          new ArrayList<>(), new ArrayList<>()
        );

      // ③ 削除対象データ作成（DelWeekList を基準）
      List<OrdMain> preDelOrdMainList = createDeleteDataByDelWeekList(treatmentInstanceList, weekResponse, facilityCd);

      // ④ 削除データを除外する
      List<TreatmentInstance> filterWeekMoveRuleList = Optional.ofNullable(treatmentInstanceList).orElse(Collections.emptyList())
        .stream().filter(i -> !weekResponse.getDelWeekList().contains(i.getTreatWeek()))
        .collect(Collectors.toList());

      // ⑤ 移動ルールと治療終了時間の計算
      List<TreatmentInstance> weekMoveRuleList = weekPatternInfoService.createMoveRuleContextFromTreatmentInstances(
        weekResponse, filterWeekMoveRuleList
      );

      // ⑥ 後処理：ChangeType = DELETE を基準に削除対象データ作成
      List<OrdMain> postDelOrdMainList =
        createDeleteDataAfterMoveRule(weekMoveRuleList, facilityCd);

      preDelOrdMainList.addAll(postDelOrdMainList);

      // ⑦ 選択情報
      IndscheduleChangeUserSelectedInfo userSelectedInfo =
        buildUserSelectedInfo(bodyData);

      // ⑧ 曜日変更チェック
      List<Long> ordNoList = Optional.ofNullable(preDelOrdMainList)
        .orElse(Collections.emptyList())
        .stream()
        .filter(Objects::nonNull)
        .map(OrdMain::getOrdNo)
        .filter(Objects::nonNull)
        .toList();

      scheduleResponse =
        changeDayOfWeekPatternCheck.validateDayOfWeekPatternChange(
          weekMoveRuleList, ordNoList, weekResponse, userSelectedInfo
        );
      if (!"SUCCESS".equals(scheduleResponse.getPROC_RESULT())) {
        return new ResponseEntity<>(scheduleResponse, status);
      }

      // ⑨ 曜日変更パターンの主処理
      changeResponse = weekPatternInfoService.processWeekdayPatternChange(bodyData, scheduleResponse, weekResponse,  userSelectedInfo, preDelOrdMainList, weekMoveRuleList);

    } catch (Exception e) {
      // #9700 イベントログに出るべきではないもの、判読不可能なログがある 20260407 mod yangxuewang start
      eventLogMessage.setLogMessage(ExcetionStackTraceToString(e));
      if (facilityCd != null) {
        eventLogMessage.setFacilityCd(facilityCd);
      }
      // #9700 イベントログに出るべきではないもの、判読不可能なログがある 20260407 mod yangxuewang end
      logService.log(
        LogLevel.ERROR,
        eventLogMessage,
        LoggingConstant.FUNCTION_CODE.FUNC_SCHEDULE_LIST,
        SERVICE_NAME.FNSI,
        null
      );
      status = HttpStatus.INTERNAL_SERVER_ERROR;
    }

    if ("SUCCESS".equals(scheduleResponse.getPROC_RESULT()) && "SUCCESS".equals(changeResponse.getPROC_RESULT())) {

      List<OrdMain> doCallNextPatOrdMainList = changeResponse.getDoCallNextPatOrdMainList();

      //指示履歴登録処理 MongoDB
      try {
        HashMap<Short, List<Short>> changeWeekList =
          weekResponse.getFromWeekCandidatesMap().entrySet().stream()
            .collect(
              Collectors.toMap(
                e -> e.getKey().shortValue(),
                e -> e.getValue().stream()
                  .map(Integer::shortValue)
                  .collect(Collectors.toList()),
                (v1, v2) -> v1,
                HashMap::new
              )
            );
        indHistoryMakeService.createWeekPatternHistory(
          bodyData,
          changeWeekList,
          weekResponse.getDelWeekList());
      } catch (Exception e) {
        //エラー
        eventLogMessage.setLogMessage("指示履歴登録処理 MongoDB " + e.getMessage());
        logService.log(LogLevel.ERROR, eventLogMessage, LoggingConstant.FUNCTION_CODE.FUNC_SCHEDULE_LIST, SERVICE_NAME.FNSI, null);
      }

      //ord_main変更履歴登録 MongoDB
      try {
        selectHistoryUtils.insertMangoDbHistoryBatchByOrdMainList(doCallNextPatOrdMainList);
      } catch (Exception e) {
        //エラー
        eventLogMessage.setLogMessage("ord_main変更履歴登録 MongoDB " + e.getMessage());
        logService.log(LogLevel.ERROR, eventLogMessage, LoggingConstant.FUNCTION_CODE.FUNC_SCHEDULE_LIST, SERVICE_NAME.FNSI, null);
      }

      //write EventLog
      try {
        eventLogOutputToMongoDBCommon.makeEvebtLogToMongoByDataDiff(changeResponse.getResultAllChangeBeforeDataInfoList(), changeResponse.getResultAllChangedDataInfoList());
      } catch (Exception e) {
        //エラー
        eventLogMessage.setLogMessage("eventLog共通処理 " + e.getMessage());
        logService.log(LogLevel.ERROR, eventLogMessage, LoggingConstant.FUNCTION_CODE.FUNC_SCHEDULE_LIST, SERVICE_NAME.FNSI, null);
      }

      // サービスの新しい次患者更新呼出統合処理を呼び出す
      try {
        nextPatService.CallNextPatChange(facilityCd, changeResponse.getDoCallNextPatOrdMainList());
      } catch (Exception e) {
        //エラー
        eventLogMessage.setLogMessage("サービスの新しい次患者更新呼出統合処理を呼び出す " + e.getMessage());
        logService.log(LogLevel.ERROR, eventLogMessage, LoggingConstant.FUNCTION_CODE.FUNC_SCHEDULE_LIST, SERVICE_NAME.FNSI, null);
      }

      // 連携関連呼出
      try {
        String actionMode = "PAT_VIEWER_WEEK_PATTERN";
        List<Long> patIdList = new ArrayList<>();
        Long updUserId = Long.parseLong(bodyData.getUpd_user());

        patIdList.add(Long.parseLong(bodyData.getPat_id()));

        List<JournalCreateRequestPayload> journalList = journalCreatePayloadService.createJournalPayload(facilityCd, changeResponse.getResultAllChangedDataInfoList(), changeResponse.getResultAllChangeBeforeDataInfoList(), patIdList, updUserId, actionMode);
        if (!org.apache.commons.collections.CollectionUtils.isEmpty(journalList)) {
          journalService.callCreateJournalForCtrNo(journalList);
        }
      } catch (Exception e) {
        //エラー
        eventLogMessage.setLogMessage("連携関連呼出 " + e.getMessage());
        logService.log(LogLevel.ERROR, eventLogMessage, LoggingConstant.FUNCTION_CODE.FUNC_SCHEDULE_LIST, SERVICE_NAME.FNSI, null);
      }
    }
    else if("PARAM_ERR".equals(scheduleResponse.getPROC_RESULT())){
      status = HttpStatus.BAD_REQUEST;
    }
    return new ResponseEntity<>(scheduleResponse, status);
  }

  public WeekPatternResponse buildWeekPatternResponse(ApiEntityOrdMain.ValiWeekPattern bodyData) {

    JSONArray weekPatternArray =
      new JSONArray(bodyData.getWeek_pattern_info());

    // パターン内に登場した元の治療週
    List<Integer> sourceWeekList = new ArrayList<>();

    Map<Integer, List<Integer>> fromWeekCandidatesMap = new HashMap<>();

    for (int i = 0; i < weekPatternArray.length(); i++) {
      JSONObject patternObj = weekPatternArray.optJSONObject(i);
      if (patternObj == null) {
        continue;
      }

      int targetWeek = patternObj.optInt("value");

      JSONArray fromWeekArray = patternObj.optJSONArray("fromWeek");
      if (fromWeekArray == null) {
        continue;
      }

      for (int j = 0; j < fromWeekArray.length(); j++) {
        int fromWeek = fromWeekArray.optInt(j);

        // 元の治療週を順序通りに保持（後続処理用）
        sourceWeekList.add(fromWeek);

        // 元週ごとに移動先候補週を集約
        fromWeekCandidatesMap
          .computeIfAbsent(fromWeek, k -> new ArrayList<>())
          .add(targetWeek);
      }
    }

    Map<Integer, Integer> changeWeekMap = new HashMap<>();

    fromWeekCandidatesMap.forEach((fromWeek, candidates) ->
      candidates.stream()
        .filter(v -> !v.equals(fromWeek))
        .min(Integer::compareTo)
        .ifPresent(minWeek ->
          changeWeekMap.put(fromWeek, minWeek)
        )
    );

    JSONArray targetWeekArray =
      Optional.ofNullable(bodyData.getMove_target_week_list())
        .map(JSONArray::new)
        .orElseGet(JSONArray::new);

    List<Integer> srcDelWeek = new ArrayList<>();
    for (int i = 0; i < targetWeekArray.length(); i++) {
      Integer weekNo = targetWeekArray.getInt(i);
      if (!sourceWeekList.contains(weekNo)) {
        srcDelWeek.add(weekNo);
      }
    }

    WeekPatternResponse response = new WeekPatternResponse();

    response.setFacilityCd(bodyData.getFacility_cd());
    response.setPatId(Long.parseLong(bodyData.getPat_id()));
    response.setIsEndDateUnset(bodyData.getIs_deadline());
    response.setFromWeekList(sourceWeekList.stream().distinct().collect(Collectors.toList()));
    response.setTreatmentCd(bodyData.getInd_treatment_cd() == null
      ? 0
      : Integer.parseInt(bodyData.getInd_treatment_cd()));
    response.setWeekChangeStartDate(bodyData.getInd_treat_start_date().replaceAll("-", ""));
    response.setWeekChangeEndDate((StringUtil.isBlank(bodyData.getEnd_date())) ? null : bodyData.getEnd_date().replace("-", ""));
    response.setFooterFlg(bodyData.getFooter_flg());
    response.setFromWeekCandidatesMap(fromWeekCandidatesMap);
    response.setChangeWeekMap(changeWeekMap);
    response.setDelWeekList(srcDelWeek);

    return response;
  }

  private List<OrdMain> createDeleteDataByDelWeekList(List<TreatmentInstance> treatmentInstanceList, WeekPatternResponse weekResponse, String facilityCd) {

    return Optional.ofNullable(treatmentInstanceList).orElse(Collections.emptyList())
      .stream().filter(i -> i.getSource() != TreatmentInstance.Source.PAT_TREATMENT_PATTERN)
      .filter(i -> weekResponse.getDelWeekList().contains(i.getTreatWeek())).map(i -> {
        OrdMain o = new OrdMain();
        o.setOrdNo(i.getOrdNo());
        o.setTreatDate(i.getTreatDate());
        o.setTreatWeek(i.getTreatWeek().shortValue());
        o.setIndKurCd(i.getKurCd());
        o.setIndBedCd(i.getBedCd());
        o.setPatId(i.getPatId());
        o.setFacilityCd(facilityCd);
        return o;
      })
      .collect(Collectors.toList());
  }

  private List<OrdMain> createDeleteDataAfterMoveRule(
    List<TreatmentInstance> weekMoveRuleList,
    String facilityCd
  ) {
    return Optional.ofNullable(weekMoveRuleList)
        .orElseGet(Collections::emptyList)
        .stream()
        .filter(i -> i.getChangeType() == TreatmentInstance.ChangeType.DELETE &&
          i.getSource() != TreatmentInstance.Source.PAT_TREATMENT_PATTERN).map(i -> {
        OrdMain o = new OrdMain();
        o.setOrdNo(i.getOrdNo());
        o.setTreatDate(i.getTreatDate());
        o.setTreatWeek(i.getTreatWeek().shortValue());
        o.setIndKurCd(i.getKurCd());
        o.setIndBedCd(i.getBedCd());
        o.setPatId(i.getPatId());
        o.setFacilityCd(facilityCd);
        return o;
      })
        .collect(Collectors.toList());
  }

